const ORIGINAL = {"pages": {"welcome": {"markup": "<!--pages/welcome/welcome.wxml-->\n<view class=\"container\">\n  <!-- 顶部logo区 -->\n  <view class=\"logo-area\">\n    <view class=\"logo-icon\">🎭</view>\n    <view class=\"app-name\">AI 数字人</view>\n    <view class=\"app-desc\">你的智能语音伙伴</view>\n  </view>\n  <!-- 第一步：微信快速登录 -->\n  <view class=\"step-section\">\n    <view class=\"step-title\">第一步：微信授权</view>\n    <view class=\"wechat-login-box\" bindtap=\"quickWechatLogin\">\n      <text class=\"wechat-icon\">💚</text>\n      <text class=\"wechat-text\">微信授权</text>\n      <view wx:if=\"{{isWechatLogin}}\" class=\"success-badge\">✓ 已登录</view>\n    </view>\n    <view class=\"tip-text\">仅获取身份信息，无需授权头像和昵称</view>\n  </view>\n  <!-- 第二步：设置资料 -->\n  <view class=\"step-section\">\n    <view class=\"step-title\">第二步：设置资料</view>\n    \n    <!-- 头像区域 -->\n    <view class=\"avatar-area\">\n      <view class=\"avatar-wrapper\" bindtap=\"chooseAvatar\">\n        <image class=\"avatar\" src=\"{{avatarUrl}}\" mode=\"aspectFill\" wx:if=\"{{avatarUrl}}\"></image>\n        <view class=\"avatar-placeholder\" wx:else>\n          <text class=\"icon\">📷</text>\n          <text class=\"text\">点击上传头像</text>\n        </view>\n      </view>\n    </view>\n    <!-- 昵称输入 -->\n    <view class=\"nickname-area\">\n      <view class=\"nickname-label\">昵称</view>\n      <input class=\"nickname-input\" placeholder=\"给自己起个名字吧\" placeholder-class=\"placeholder\" value=\"{{nickname}}\" bindinput=\"onNicknameInput\" maxlength=\"20\"></input>\n    </view>\n  </view>\n  <!-- 开始按钮 -->\n  <view class=\"btn-area\">\n    <button class=\"btn-start\" bindtap=\"saveCustomUserInfo\" hover-class=\"btn-hover\" disabled=\"{{!isWechatLogin || !nickname}}\">\n      {{isWechatLogin ? (nickname ? '开始体验' : '请输入昵称') : '请先微信授权'}}\n    </button>\n  </view>\n</view>", "css": ".container {\n  min-height: var(--page-height);\n  background: linear-gradient(180deg, #fff8f0 0%, #ffe4c9 50%, #ffd4a3 100%);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  padding: 0 calc(48 * var(--rpx));\n  box-sizing: border-box;\n}\n\n.logo-area {\n  margin-top: calc(60 * var(--rpx));\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n\n.logo-icon { font-size: calc(100 * var(--rpx)); margin-bottom: calc(12 * var(--rpx)); }\n.app-name { font-size: calc(44 * var(--rpx)); font-weight: bold; color: #8b4513; letter-spacing: calc(4 * var(--rpx)); }\n.app-desc { font-size: calc(24 * var(--rpx)); color: #a0522d; margin-top: calc(8 * var(--rpx)); }\n\n.step-section { width: 100%; margin-top: calc(40 * var(--rpx)); }\n.step-title { font-size: calc(28 * var(--rpx)); font-weight: bold; color: #8b4513; margin-bottom: calc(20 * var(--rpx)); }\n\n.wechat-login-box {\n  width: 100%; height: calc(100 * var(--rpx));\n  background: #07c160;\n  border-radius: calc(50 * var(--rpx));\n  display: flex; align-items: center; justify-content: center; gap: calc(16 * var(--rpx));\n  position: relative;\n}\n.wechat-icon { font-size: calc(40 * var(--rpx)); }\n.wechat-text { font-size: calc(32 * var(--rpx)); color: #fff; font-weight: 500; }\n.success-badge {\nposition: absolute; right: calc(30 * var(--rpx));\nfont-size: calc(24 * var(--rpx)); color: #fff;\nbackground: rgba(255,255,255,0.3); padding: calc(6 * var(--rpx)) calc(16 * var(--rpx)); border-radius: calc(20 * var(--rpx));\n}\n.tip-text { margin-top: calc(16 * var(--rpx)); font-size: calc(24 * var(--rpx)); color: #a0522d; opacity: 0.7; text-align: center; }\n\n.avatar-area { display: flex; flex-direction: column; align-items: center; }\n.avatar-wrapper { width: calc(180 * var(--rpx)); height: calc(180 * var(--rpx)); border-radius: 50%; overflow: hidden; border: calc(4 * var(--rpx)) solid #ff8c00; }\n.avatar { width: 100%; height: 100%; }\n.avatar-placeholder { width: 100%; height: 100%; background: rgba(255,140,0,0.1); display: flex; flex-direction: column; align-items: center; justify-content: center; }\n.avatar-placeholder .icon { font-size: calc(50 * var(--rpx)); margin-bottom: calc(8 * var(--rpx)); }\n.avatar-placeholder .text { font-size: calc(20 * var(--rpx)); color: #a0522d; }\n\n.nickname-area { width: 100%; margin-top: calc(32 * var(--rpx)); }\n.nickname-label { font-size: calc(28 * var(--rpx)); color: #a0522d; margin-bottom: calc(12 * var(--rpx)); padding-left: calc(8 * var(--rpx)); }\n.nickname-input { width: 100%; height: calc(88 * var(--rpx)); background: #fff; border-radius: calc(44 * var(--rpx)); padding: 0 calc(36 * var(--rpx)); box-sizing: border-box; font-size: calc(30 * var(--rpx)); color: #5a3a00; text-align: center; border: calc(2 * var(--rpx)) solid #ffd4a3; }\n.placeholder { color: #a0522d; }\n\n.btn-area { width: 100%; margin-top: calc(48 * var(--rpx)); }\n.btn-start { width: 100%; height: calc(96 * var(--rpx)); border-radius: calc(48 * var(--rpx)); font-size: calc(32 * var(--rpx)); font-weight: 500; display: flex; align-items: center; justify-content: center; background: #ff8c00; color: #fff; border: none; }\n.btn-hover { opacity: 0.8; transform: scale(0.98); }\n.btn-start[disabled] { background: #ccc; color: #fff; }", "js": "// pages/welcome/welcome.js\nvar app = getApp();\nPage({\ndata: {\napiBaseUrl: 'http://127.0.0.1:9',\navatarUrl: '',\nnickname: '',\nhasAvatar: false,\nisWechatLogin: false\n},\n\nonLoad: function() {\nvar userInfo = wx.getStorageSync('userInfo');\nif (!userInfo || !userInfo.nickname) {\n  userInfo = {\n    nickname: '测试用户',\n    avatar: '',\n    wechatBound: false,\n    offlineMode: true\n  };\n  wx.setStorageSync('userInfo', userInfo);\n  wx.setStorageSync('openid', 'wx_local_demo_' + Date.now());\n}\nif (userInfo.nickname) {\nwx.switchTab({ url: '/pages/index/index' });\nreturn;\n}\nvar openid = wx.getStorageSync('openid');\nif (openid && openid.startsWith('wx_')) {\n  this.setData({ isWechatLogin: true });\n}\n},\n\n// 微信快速登录\nquickWechatLogin: function() {\n// 离线体验模式：不把微信登录临时代码发送到外部服务器。\nvar mockOpenid = 'wx_local_demo_' + Date.now();\nwx.setStorageSync('openid', mockOpenid);\nthis.setData({ isWechatLogin: true });\nwx.showToast({ title: '已进入离线模式', icon: 'success' });\n},\n\n// 上传头像（需先微信登录）\nchooseAvatar: function() {\nvar that = this;\nif (!this.data.isWechatLogin) {\n  wx.showModal({\n    title: '请先微信登录',\n    content: '请先点击\"微信快速登录\"获取身份',\n    showCancel: false,\n    confirmText: '知道了'\n  });\n  return;\n}\nwx.chooseMedia({\n  count: 1,\n  mediaType: ['image'],\n  sourceType: ['album', 'camera'],\n  success: function(res) {\n    // 仅使用本机临时文件，不上传头像。\n    that.setData({\n      avatarUrl: res.tempFiles[0].tempFilePath,\n      hasAvatar: true\n    });\n    wx.showToast({ title: '头像仅保存在本机', icon: 'success' });\n  }\n});\n},\n\nonNicknameInput: function(e) {\nthis.setData({ nickname: e.detail.value });\n},\n\n// 保存用户信息（需先微信登录）\nsaveCustomUserInfo: function() {\nvar that = this;\nif (!this.data.isWechatLogin) {\n  wx.showModal({\n    title: '请先微信登录',\n    content: '请先点击\"微信快速登录\"获取身份',\n    showCancel: false,\n    confirmText: '知道了'\n  });\n  return;\n}\nvar nickname = that.data.nickname.trim();\nif (!nickname) {\n  wx.showToast({ title: '请输入昵称', icon: 'none' });\n  return;\n}\nvar userInfo = {\n  nickname: nickname,\n  avatar: that.data.avatarUrl || '',\n  wechatBound: false,\n  offlineMode: true\n};\nwx.setStorageSync('userInfo', userInfo);\nwx.showToast({ title: '已保存到本机', icon: 'success' });\nsetTimeout(function() {\n  wx.switchTab({ url: '/pages/index/index' });\n}, 500);\n}\n});\n"}, "index": {"markup": "<!--pages/index/index.wxml - 汤姆猫风格数字人主页（Telegram风格聊天界面）-->\n<view class=\"container\" style=\"background: {{themeColors.gradient}}\">\n  <!-- 顶部栏 -->\n  <view class=\"header\">\n    <view class=\"user-btn\" bindtap=\"goToUser\">\n      <image wx:if=\"{{userAvatar}}\" src=\"{{userAvatar}}\" class=\"user-avatar-img\" mode=\"aspectFill\"></image>\n      <text wx:else>👤</text>\n    </view>\n  </view>\n\n  <!-- 数字人展示区 -->\n  <view class=\"avatar-section\">\n    <view \n      class=\"digital-human {{expression}} {{currentStatus}} {{isAnimating ? 'animating' : ''}}\"\n      bindtap=\"tapHead\"\n    >\n      <image wx:if=\"{{avatarUrl}}\" src=\"{{avatarUrl}}\" mode=\"aspectFill\" class=\"human-image\"></image>\n      <view wx:else class=\"human-placeholder\" bindtap=\"changeAvatar\">\n        <text class=\"plus\">+</text>\n        <text class=\"tip\">点击设置形象</text>\n      </view>\n      <view class=\"mouth-overlay\"></view>\n    </view>\n  </view>\n\n  <!-- 状态文字 -->\n  <view class=\"status-bar\">\n    <text class=\"status-text\">{{statusText}}</text>\n  </view>\n\n  <!-- Telegram风格对话气泡区域 -->\n  <scroll-view scroll-y class=\"chat-container\" wx:if=\"{{messages.length > 0}}\" scroll-into-view=\"{{scrollIntoView}}\">\n    <block wx:for=\"{{messages}}\" wx:key=\"id\">\n      <view wx:if=\"{{item.role === 'user'}}\" class=\"message-row message-user-row\">\n        <view class=\"message-bubble message-user-bubble\">\n          <text>{{item.content}}</text>\n        </view>\n      </view>\n      <view wx:else class=\"message-row message-ai-row\">\n        <view class=\"message-bubble message-ai-bubble\">\n          <text>{{item.content}}</text>\n        </view>\n      </view>\n    </block>\n    <view id=\"scroll-bottom\"></view>\n  </scroll-view>\n\n  <!-- 对话区（文字模式时显示） -->\n  <view wx:if=\"{{subMode === 'chat'}}\" class=\"chat-section\">\n    <view class=\"input-bar\">\n      <input class=\"text-input\" value=\"{{inputValue}}\" placeholder=\"输入文字对话...\" bindinput=\"onInput\" confirm-type=\"send\" bindconfirm=\"sendText\" />\n      <button class=\"send-btn\" style=\"background: {{themeColors.primary}}\" bindtap=\"sendText\">发送</button>\n    </view>\n  </view>\n\n  <!-- 功能切换区 -->\n  <view class=\"mode-tabs\">\n    <view class=\"tab-item {{subMode === 'chat' ? 'active' : ''}}\" style=\"{{subMode === 'chat' ? 'color:' + themeColors.primary + ';border-color:' + themeColors.primary : ''}}\" bindtap=\"setSubMode\" data-mode=\"chat\">\n      <text class=\"tab-icon\">💬</text><text class=\"tab-text\">对话</text>\n    </view>\n    <view class=\"tab-item {{subMode === 'voice' ? 'active' : ''}}\" style=\"{{subMode === 'voice' ? 'color:' + themeColors.primary + ';border-color:' + themeColors.primary : ''}}\" bindtap=\"setSubMode\" data-mode=\"voice\">\n      <text class=\"tab-icon\">🎤</text><text class=\"tab-text\">语音</text>\n    </view>\n    <view class=\"tab-item {{subMode === 'avatar' ? 'active' : ''}}\" style=\"{{subMode === 'avatar' ? 'color:' + themeColors.primary + ';border-color:' + themeColors.primary : ''}}\" bindtap=\"setSubMode\" data-mode=\"avatar\">\n      <text class=\"tab-icon\">🖼️</text><text class=\"tab-text\">形象</text>\n    </view>\n    <view class=\"tab-item {{subMode === 'sound' ? 'active' : ''}}\" style=\"{{subMode === 'sound' ? 'color:' + themeColors.primary + ';border-color:' + themeColors.primary : ''}}\" bindtap=\"setSubMode\" data-mode=\"sound\">\n      <text class=\"tab-icon\">🔊</text><text class=\"tab-text\">声音</text>\n    </view>\n  </view>\n\n  <!-- 语音模式 -->\n  <view wx:if=\"{{subMode === 'voice'}}\" class=\"voice-section\">\n    <view class=\"record-btn {{isRecording ? 'recording' : ''}}\" style=\"background: {{isRecording ? '#e74c3c' : themeColors.primary}}\" bindtouchstart=\"startRecording\" bindtouchend=\"stopRecording\">\n      <text class=\"record-icon\">{{isRecording ? '🔴' : '🎤'}}</text>\n      <text class=\"record-text\">{{isRecording ? '松开结束' : '按住说话'}}</text>\n    </view>\n  </view>\n\n  <!-- 形象模式 -->\n  <view wx:if=\"{{subMode === 'avatar'}}\" class=\"avatar-list-section\">\n    <view class=\"section-header\">\n      <text class=\"section-title\">我的形象</text>\n<text class=\"change-btn\" style=\"color: {{themeColors.primary}}\" bindtap=\"changeAvatar\">+ 上传新形象</text>\n</view>\n<scroll-view scroll-x class=\"avatar-scroll\">\n<view wx:for=\"{{avatarList}}\" wx:key=\"id\" class=\"avatar-item {{avatarUrl === item.url ? 'selected' : ''}}\" style=\"{{avatarUrl === item.url ? 'border-color:' + themeColors.primary : ''}}\" bindtap=\"selectAvatar\" data-url=\"{{item.url}}\">\n<image src=\"{{item.url}}\" mode=\"aspectFill\"></image>\n</view>\n</scroll-view>\n</view>\n\n\n<view wx:if=\"{{subMode === 'sound'}}\" class=\"sound-list-section\">\n<view class=\"section-header\">\n<text class=\"section-title\">我的声音</text>\n<text class=\"change-btn\" style=\"color: {{themeColors.primary}}\" bindtap=\"goToVoiceClone\">+ 克隆新声音</text>\n</view>\n<view wx:for=\"{{soundList}}\" wx:key=\"id\" class=\"sound-item {{currentSound.id === item.id ? 'selected' : ''}}\" style=\"{{currentSound.id === item.id ? 'border-color:' + themeColors.primary + ';background:' + themeColors.gradient : ''}}\" bindtap=\"selectSound\" data-sound=\"{{item}}\">\n<text class=\"sound-name\">{{item.name || '克隆声音' + (index + 1)}}</text>\n<view class=\"sound-actions\">\n<text class=\"play-icon {{playingSoundId === item.id ? 'playing' : ''}}\" catchtap=\"playSound\" data-url=\"{{item.voice_url}}\" data-speaker-id=\"{{item.speaker_id}}\" data-id=\"{{item.id}}\">{{playingSoundId === item.id && isPlaying ? '⏸' : '▶'}}</text>\n</view>\n</view>\n</view>\n\n<view class=\"bottom-safe\"></view>\n\n<view class=\"ai-create-section\">\n<button class=\"ai-create-btn\" style=\"background: {{themeColors.primary}}\" bindtap=\"goToGenerate\">🎨 AI创作（文生图/图生图）</button>\n</view>\n</view>", "css": "/* pages/index/index.wxss - 汤姆猫风格数字人主页 */\n\n.container {\n  min-height: var(--page-height);\n  display: flex;\n  flex-direction: column;\n}\n\n/* 顶部栏 */\n.header {\n  padding: calc(20 * var(--rpx));\n  display: flex;\n  justify-content: flex-end;\n}\n\n.user-btn {\n  width: calc(80 * var(--rpx));\n  height: calc(80 * var(--rpx));\n  border-radius: 50%;\n  background: #fff;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: calc(40 * var(--rpx));\n}\n\n.user-avatar-img {\n  width: calc(80 * var(--rpx));\n  height: calc(80 * var(--rpx));\n  border-radius: 50%;\n}\n\n/* 数字人展示区 */\n.avatar-section {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  padding: calc(40 * var(--rpx));\n}\n\n.digital-human {\n  width: calc(300 * var(--rpx));\n  height: calc(300 * var(--rpx));\n  border-radius: 50%;\n  overflow: hidden;\n  position: relative;\n}\n\n.human-image {\n  width: 100%;\n  height: 100%;\n}\n\n.human-placeholder {\n  width: 100%;\n  height: 100%;\n  background: linear-gradient(135deg, #ddd, #eee);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n}\n\n.plus {\n  font-size: calc(80 * var(--rpx));\n  color: #999;\n}\n\n.tip {\n  font-size: calc(24 * var(--rpx));\n  color: #999;\n  margin-top: calc(10 * var(--rpx));\n}\n\n.mouth-overlay {\n  position: absolute;\n  bottom: calc(60 * var(--rpx));\n  left: 50%;\n  transform: translateX(-50%);\n  width: calc(40 * var(--rpx));\n  height: calc(20 * var(--rpx));\n  background: #ff6b6b;\n  border-radius: calc(20 * var(--rpx));\n  opacity: 0;\n}\n\n.digital-human.speaking .mouth-overlay {\n  opacity: 1;\n  animation: mouthMove 0.3s ease-in-out infinite;\n}\n\n@keyframes mouthMove {\n  0%, 100% { height: calc(20 * var(--rpx)); }\n  50% { height: calc(40 * var(--rpx)); }\n}\n\n/* 状态栏 */\n.status-bar {\n  text-align: center;\n  padding: calc(20 * var(--rpx));\n}\n\n.status-text {\n  font-size: calc(28 * var(--rpx));\n  color: #666;\n}\n\n/* ====== Telegram 风格聊天气泡样式 ====== */\n.chat-container {\n  max-height: calc(350 * var(--rpx));\n  padding: calc(20 * var(--rpx));\n  overflow-y: auto;\n}\n\n.message-row {\n  display: flex;\n  margin-bottom: calc(16 * var(--rpx));\n}\n\n.message-user-row {\n  justify-content: flex-end;\n}\n\n.message-ai-row {\n  justify-content: flex-start;\n}\n\n.message-bubble {\n  max-width: 70%;\n  padding: calc(20 * var(--rpx)) calc(28 * var(--rpx));\n  border-radius: calc(24 * var(--rpx));\n  font-size: calc(28 * var(--rpx));\n  line-height: 1.5;\n  word-wrap: break-word;\n}\n\n.message-user-bubble {\n  background: linear-gradient(135deg, #ffb347, #ff8c00);\n  color: #fff;\n  border-bottom-right-radius: calc(8 * var(--rpx));\n}\n\n.message-ai-bubble {\n  background: #e5e5e5;\n  color: #333;\n  border-bottom-left-radius: calc(8 * var(--rpx));\n}\n\n/* ====== 对话区输入框 ====== */\n.chat-section {\n  padding: calc(20 * var(--rpx));\n  background: #fff;\n}\n\n.input-bar {\n  display: flex;\n  align-items: center;\n  background: #f5f5f5;\n  border-radius: calc(40 * var(--rpx));\n  padding: calc(10 * var(--rpx)) calc(16 * var(--rpx));\n}\n\n.text-input {\n  flex: 1;\n  height: calc(72 * var(--rpx));\n  font-size: calc(30 * var(--rpx));\n  padding: 0 calc(16 * var(--rpx));\n}\n\n.send-btn {\n  width: calc(120 * var(--rpx));\n  height: calc(72 * var(--rpx));\n  line-height: calc(72 * var(--rpx));\n  margin-left: calc(16 * var(--rpx));\n  border-radius: calc(36 * var(--rpx));\n  color: #fff;\n  font-size: calc(28 * var(--rpx));\n  padding: 0;\n}\n\n/* ====== 功能切换区 ====== */\n.mode-tabs {\n  display: flex;\n  background: #fff;\n  padding: calc(16 * var(--rpx));\n  border-radius: calc(16 * var(--rpx));\n  margin: calc(20 * var(--rpx));\n}\n\n.tab-item {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  padding: calc(16 * var(--rpx));\n  border-radius: calc(12 * var(--rpx));\n}\n\n.tab-icon {\n  font-size: calc(40 * var(--rpx));\n}\n\n.tab-text {\n  font-size: calc(24 * var(--rpx));\n  margin-top: calc(8 * var(--rpx));\n  color: #666;\n}\n\n.tab-item.active {\n  background: rgba(255, 179, 71, 0.1);\n}\n\n/* ====== 语音模式 ====== */\n.voice-section {\n  padding: calc(40 * var(--rpx));\n  display: flex;\n  justify-content: center;\n}\n\n.record-btn {\n  width: calc(300 * var(--rpx));\n  height: calc(300 * var(--rpx));\n  border-radius: 50%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  box-shadow: 0 calc(8 * var(--rpx)) calc(30 * var(--rpx)) rgba(0,0,0,0.2);\n}\n\n.record-btn.recording {\n  animation: pulse 1s ease-in-out infinite;\n}\n\n@keyframes pulse {\n  0%, 100% { transform: scale(1); }\n  50% { transform: scale(1.05); }\n}\n\n.record-icon {\n  font-size: calc(80 * var(--rpx));\n}\n\n.record-text {\n  color: #fff;\n  font-size: calc(28 * var(--rpx));\n  margin-top: calc(16 * var(--rpx));\n}\n\n/* ====== 形象模式 ====== */\n.avatar-list-section {\n  padding: calc(20 * var(--rpx));\n  background: #fff;\n  margin: calc(20 * var(--rpx));\n  border-radius: calc(16 * var(--rpx));\n}\n\n.section-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\nmargin-bottom: calc(20 * var(--rpx));\n}\n\n.section-title {\nfont-size: calc(32 * var(--rpx));\nfont-weight: bold;\n}\n\n.change-btn {\nfont-size: calc(28 * var(--rpx));\n}\n\n.avatar-scroll {\nwhite-space: nowrap;\n}\n\n.avatar-item {\ndisplay: inline-block;\nwidth: calc(160 * var(--rpx));\nheight: calc(160 * var(--rpx));\nmargin-right: calc(20 * var(--rpx));\nborder-radius: calc(16 * var(--rpx));\noverflow: hidden;\nborder: calc(4 * var(--rpx)) solid transparent;\n}\n\n.avatar-item image {\nwidth: 100%;\nheight: 100%;\n}\n\n.avatar-item.selected {\nborder-color: #ff8c00;\n}\n\n/* ====== 声音模式 ====== */\n.sound-list-section {\npadding: calc(20 * var(--rpx));\nbackground: #fff;\nmargin: calc(20 * var(--rpx));\nborder-radius: calc(16 * var(--rpx));\n}\n\n.sound-item {\ndisplay: flex;\njustify-content: space-between;\nalign-items: center;\npadding: calc(24 * var(--rpx));\nborder-bottom: calc(1 * var(--rpx)) solid #eee;\n}\n\n.sound-item:last-child {\nborder-bottom: none;\n}\n\n.sound-item.selected {\nbackground: rgba(255, 179, 71, 0.1);\n}\n\n.sound-name {\nfont-size: calc(28 * var(--rpx));\n}\n\n.sound-actions {\ndisplay: flex;\nalign-items: center;\n}\n\n.play-icon {\nfont-size: calc(40 * var(--rpx));\npadding: calc(16 * var(--rpx));\n}\n\n.play-icon.playing {\ncolor: #ff8c00;\n}\n\n/* ====== 底部安全区 ====== */\n.bottom-safe {\nheight: calc(40 * var(--rpx));\n}\n\n/* ====== AI创作按钮 ====== */\n.ai-create-section {\npadding: calc(20 * var(--rpx));\ntext-align: center;\n}\n\n.ai-create-btn {\nwidth: 80%;\nheight: calc(88 * var(--rpx));\nline-height: calc(88 * var(--rpx));\nborder-radius: calc(44 * var(--rpx));\ncolor: #fff;\nfont-size: calc(30 * var(--rpx));\n}", "js": "// pages/index/index.js - 汤姆猫风格数字人主页\nvar app = getApp();\nPage({\ndata: {\napiBaseUrl: 'http://127.0.0.1:9',\nuserInfo: {},\nuserAvatar: '',\navatarUrl: '',\nhasAvatar: false,\ncurrentStatus: 'idle',\nstatusText: '点击与我对话',\nlastReply: '',\nisRecording: false,\nisPlaying: false,\nplayingSoundId: null,\nsubMode: 'chat',\nsubModeText: {\nchat: '文字对话',\nvoice: '语音对话',\navatar: '我的形象',\nsound: '我的声音'\n},\nmessages: [],\ninputValue: '',\navatarList: [],\nsoundList: [],\ncurrentSound: {},\nexpression: 'idle',\nisAnimating: false,\nthemeColors: {},\nscrollIntoView: ''\n},\n\nonLoad: function() {\nthis.loadUserData();\nthis.initRecorder();\nthis.applyTheme();\n},\n\nonShow: function() {\nvar that = this;\nwx.getStorage({\nkey: 'digitalAvatar',\nsuccess: function(res) {\nif (res.data) {\nthat.setData({ avatarUrl: res.data, hasAvatar: true });\n} else {\nthat.setData({ avatarUrl: '', hasAvatar: false });\n}\n},\nfail: function() {\nthat.setData({ avatarUrl: '', hasAvatar: false });\n}\n});\nthis.refreshData();\nthis.applyTheme();\n},\n\nloadUserData: function() {\nvar that = this;\nwx.getStorage({\nkey: 'userInfo',\nsuccess: function(res) {\nthat.setData({ userInfo: res.data || {} });\n}\n});\nwx.getStorage({\nkey: 'currentSound',\nsuccess: function(res) {\nif (res.data) {\nthat.setData({ currentSound: res.data });\n}\n}\n});\n},\n\nrefreshData: function() {\nthis.loadUserData();\nthis.loadAvatarList();\nthis.loadSoundList();\n},\n\napplyTheme: function() {\nvar that = this;\nvar theme = wx.getStorageSync('theme') || '默认';\nvar themeColors = app.themeConfig[theme] || app.themeConfig['默认'];\nthis.setData({ themeColors: themeColors });\nwx.setNavigationBarColor({\nfrontColor: '#ffffff',\nbackgroundColor: themeColors.primary,\nanimation: { duration: 300, timingFunc: 'easeInOut' }\n});\n},\n\nloadAvatarList: function() {\nthis.setData({ avatarList: wx.getStorageSync('webAvatars') || [] });\n},\n\nloadSoundList: function() {\nthis.setData({ soundList: wx.getStorageSync('clonedVoices') || [] });\n},\n\ninitRecorder: function() {\nvar that = this;\ntry {\nthis.recorderManager = wx.getRecorderManager();\nthis.recorderManager.onStop(function(res) {\nthat.handleAudioStop(res.tempFilePath);\n});\nthis.recorderManager.onError(function(err) {\nthat.setData({ isRecording: false, currentStatus: 'idle', statusText: '录音失败' });\n});\n} catch(e) {\nconsole.error('initRecorder error:', e);\n}\n},\n\nsetSubMode: function(e) {\nvar mode = e.currentTarget.dataset.mode;\nthis.setData({ subMode: mode, statusText: this.data.subModeText[mode] });\n},\n\ntapHead: function() {\nthis.playExpression('happy');\nthis.setData({ statusText: '你好呀！😊' });\n},\n\ntapBody: function() {\nthis.playExpression('surprised');\nthis.setData({ statusText: '哎呀！😮' });\n},\n\nplayExpression: function(expression) {\nvar that = this;\nthis.setData({ expression: expression, isAnimating: true });\nsetTimeout(function() {\nthat.setData({ expression: 'idle', isAnimating: false });\n}, 2000);\n},\n\nstartRecording: function() {\nvar that = this;\nif (!this.data.hasAvatar) {\nwx.showToast({ title: '请先设置数字人形象', icon: 'none' });\nreturn;\n}\nthis.setData({ isRecording: true, currentStatus: 'listening', statusText: '我在听...' });\ntry {\nthis.recorderManager.start({ format: 'wav', duration: 30000, sampleRate: 16000 });\n} catch(e) {\nthat.setData({ isRecording: false, currentStatus: 'idle', statusText: '录音失败' });\n}\n},\n\nstopRecording: function() {\nif (this.recorderManager) {\nthis.recorderManager.stop();\n}\n},\n\nhandleAudioStop: function(filePath) {\nvar that = this;\nvar fs = wx.getFileSystemManager();\nthis.setData({ isRecording: false, currentStatus: 'thinking', statusText: '思考中...' });\nfs.readFile({\nfilePath: filePath,\nencoding: 'base64',\nsuccess: function(data) {\nthat.processVoice(data.data);\n},\nfail: function(err)\n{\nwx.showToast({ title: '读取音频失败', icon: 'none' });\nthat.setData({ currentStatus: 'idle', statusText: '请重试' });\n}\n});\n},\n\nprocessVoice: function(audioBase64) {\nvar that = this;\nwx.request({\nurl: that.data.apiBaseUrl + '/api/voice-chat',\nmethod: 'POST',\nheader: { 'Content-Type': 'application/json' },\ndata: { audioBase64: audioBase64, speakerId: 'S_9IlkOK7X1' },\ntimeout: 120000,\nsuccess: function(res) {\nif (res.data && (res.data.success || res.data.replyText || res.data.text)) {\nvar replyText = res.data.replyText || res.data.text || '';\nvar audioData = res.data.audio;\nvar audioUrl = res.data.audioUrl;\nthat.setData({ lastReply: replyText, currentStatus: 'speaking', statusText: replyText });\nif (audioUrl) { that.playAudioUrl(audioUrl); }\nelse if (audioData) { that.playAudio(audioData); }\nthat.addMessage({ role: 'user', content: '[语音]' });\nthat.addMessage({ role: 'assistant', content: replyText });\n} else {\nthat.setData({ currentStatus: 'idle', statusText: '回答失败' });\n}\n},\nfail: function() {\nwx.showToast({ title: '网络错误', icon: 'none' });\nthat.setData({ currentStatus: 'idle', statusText: '请重试' });\n}\n});\n},\n\nplayAudio: function(base64Data) {\nvar that = this;\nvar array = wx.base64ToArrayBuffer(base64Data);\nvar filePath = wx.env.USER_DATA_PATH + '/reply_' + Date.now() + '.mp3';\nvar fs = wx.getFileSystemManager();\nfs.writeFileSync(filePath, array, 'binary');\nthis.audioContext = wx.createInnerAudioContext();\nthis.audioContext.src = filePath;\nthis.audioContext.play();\nthis.audioContext.onEnded(function() {\nthat.setData({ isPlaying: false, currentStatus: 'idle', statusText: '点击与我对话' });\n});\n},\n\nplayAudioUrl: function(url) {\nvar that = this;\nthis.stopAudio();\nthis.audioContext = wx.createInnerAudioContext();\nthis.audioContext.src = url;\nthis.audioContext.play();\nthis.audioContext.onPlay(function() { that.setData({ isPlaying: true }); });\nthis.audioContext.onEnded(function() { that.setData({ isPlaying: false, currentStatus: 'idle', statusText: '点击与我对话' }); });\n},\n\nonInput: function(e) {\nthis.setData({ inputValue: e.detail.value });\n},\n\nsendText: function() {\nvar that = this;\nvar text = this.data.inputValue;\nif (!text.trim()) { wx.showToast({ title: '请输入内容', icon: 'none' }); return; }\nthis.setData({ currentStatus: 'thinking', statusText: '思考中...', inputValue: '' });\nwx.request({\nurl: that.data.apiBaseUrl + '/api/chat',\nmethod: 'POST',\nheader: { 'Content-Type': 'application/json' },\ndata: { message: text },\nsuccess: function(res) {\nif (res.data && res.data.success) {\nvar reply = res.data.reply;\nthat.setData({ lastReply: reply, currentStatus: 'speaking', statusText: reply });\nthat.addMessage({ role: 'user', content: text });\nthat.addMessage({ role: 'assistant', content: reply });\n} else {\nthat.setData({ currentStatus: 'idle', statusText: '回答失败' });\n}\n},\nfail: function() {\nwx.showToast({ title: '网络错误', icon: 'none' });\nthat.setData({ currentStatus: 'idle', statusText: '请重试' });\n}\n});\n},\n\naddMessage: function(msg) {\nvar list = this.data.messages;\nlist.push({ id: Date.now(), role: msg.role, content: msg.content, time: new Date().toLocaleTimeString() });\nif (list.length > 20) { list = list.slice(-20); }\nthis.setData({ messages: list, scrollIntoView: 'scroll-bottom' });\n},\n\nchangeAvatar: function() {\n  var that = this;\n  wx.chooseMedia({\n    count: 1,\n    mediaType: ['image'],\n    sourceType: ['album', 'camera'],\n    success: function(res) {\n      var tempPath = res.tempFiles[0].tempFilePath;\n      wx.showLoading({ title: '上传中...' });\n      wx.uploadFile({\n        url: that.data.apiBaseUrl + '/api/upload',\n        filePath: tempPath,\n        name: 'image',\n        header: { 'x-user-openid': wx.getStorageSync('openid') || 'default' },\n        success: function(uploadRes) {\n          var data = JSON.parse(uploadRes.data);\n          console.log('上传结果:', data); \n          if (data.success) {\n            console.log('rawUrl:', data.rawUrl);\n            var rawUrl = data.rawUrl || data.url.replace('github.com', 'raw.githubusercontent.com').replace('/blob/', '/')+ '?v=' + Date.now();;\n            var list = that.data.avatarList || [];\n            list.unshift({ id: Date.now(), url: rawUrl });\n            wx.setStorageSync('digitalAvatar', rawUrl); wx.setStorageSync('webAvatars', list);\n            that.setData({\n              userAvatar: rawUrl,\n              avatarUrl: rawUrl,\n              avatarList: list,\n              hasAvatar: true,\n              statusText: '形象已更新！'\n            });\n            wx.showToast({ title: '设置成功', icon: 'success' });\n          } else {\n            wx.showToast({ title: '上传失败', icon: 'none' });\n          }\n        },\n        fail: function() { wx.showToast({ title: '上传失败', icon: 'none' }); },\n        complete: function() { wx.hideLoading(); }\n      });\n    }\n  });\n},\n\nselectAvatar: function(e) {\nvar that = this;\nvar url = e.currentTarget.dataset.url;\nwx.setStorageSync('digitalAvatar', url);\nthat.setData({ avatarUrl: url, hasAvatar: true, statusText: '形象已切换' });\n},\n\nselectSound: function(e) {\nvar sound = e.currentTarget.dataset.sound;\nwx.setStorageSync('currentSound', sound);\nthis.setData({ currentSound: sound, statusText: '已选择: ' + (sound.name || '克隆声音') });\n},\n\nplaySound: function(e) {\nvar that = this;\nvar url = e.currentTarget.dataset.url;\nvar speakerId = e.currentTarget.dataset.speakerId;\nvar soundId = e.currentTarget.dataset.id;\nif (that.data.playingSoundId === soundId && that.data.isPlaying) {\nif (that.audioContext) { that.audioContext.pause(); that.setData({ isPlaying: false }); }\nreturn;\n}\nif (that.data.playingSoundId && that.data.isPlaying) { that.stopAudio(); that.setData({ playingSoundId: null, isPlaying: false }); }\nif (url && url.startsWith('cloned:')) {\nvar sid = speakerId || url.replace('cloned:', '');\nwx.showLoading({ title: '生成语音中...' });\nwx.request({\nurl: that.data.apiBaseUrl + '/api/voice/tts',\nmethod: 'POST',\nheader: { 'Content-Type': 'application/json' },\ndata: { text: '你好，这是我克隆的声音', speakerId: sid },\nsuccess: function(res) {\nwx.hideLoading();\nif (res.data && res.data.audio) {\nif (res.data.audio.startsWith('http')) {\nwx.downloadFile({\nurl: res.data.audio,\nsuccess: function(downloadRes) {\nthat.stopAudio();\nthat.audioContext = wx.createInnerAudioContext();\nthat.audioContext.src = downloadRes.tempFilePath;\nthat.audioContext.play();\nthat.setData({ playingSoundId: soundId, isPlaying: true });\nthat.audioContext.onEnded(function() { that.setData({ playingSoundId: null, isPlaying: false }); });\n}\n});\n} else {\nthat.setData({ playingSoundId: soundId, isPlaying: true });\nthat.playAudio(res.data.audio);\n}\n} else { wx.showToast({ title: '生成失败', icon: 'none' }); }\n},\nfail: function() { wx.hideLoading(); wx.showToast({ title: '网络错误', icon: 'none' }); }\n});\nreturn;\n}\nif (url) {\nwx.downloadFile({\nurl: url,\nsuccess: function(res) {\nthat.setData({ playingSoundId: soundId, isPlaying: true });\nthat.stopAudio();\nthat.audioContext = wx.createInnerAudioContext();\nthat.audioContext.src = res.tempFilePath;\nthat.audioContext.play();\nthat.audioContext.onEnded(function() { that.setData({ playingSoundId: null, isPlaying: false }); });\n}\n});\n}\n},\n\nstopAudio: function() {\nif (this.audioContext) { this.audioContext.stop(); this.setData({ isPlaying: false, currentStatus: 'idle' }); }\n},\n\ngoToSettings: function() { wx.navigateTo({ url: '/pages/settings/settings' }); },\ngoToUser: function() { wx.switchTab({ url: '/pages/settings/settings' }); },\ngoToVoiceClone: function() { wx.navigateTo({ url: '/pages/voice-clone/voice-clone' }); },\ngoToGenerate: function() { wx.navigateTo({ url: '/pages/generate/generate' }); }\n});\n"}, "digital": {"markup": "<!--pages/digital/digital.wxml-->\n<view class=\"container\" style=\"background: {{themeColors.gradient}}\">\n  <!-- 头部 -->\n  <view class=\"header\" style=\"background: {{themeColors.header}}\">\n    <text class=\"title\">数字人专区</text>\n    <text class=\"subtitle\">上传照片，生成专属数字人视频</text>\n  </view>\n\n  <!-- 数字人图片上传（最多9张） -->\n  <view class=\"section\">\n    <view class=\"section-header\">\n      <text class=\"section-title\">数字人形象（最多9张）</text>\n      <text class=\"section-hint\">{{userImages.length}}/9</text>\n    </view>\n    <view class=\"images-grid\">\n      <view class=\"image-item\" wx:for=\"{{userImages}}\" wx:key=\"index\">\n        <image src=\"{{item}}\" mode=\"aspectFill\" class=\"thumb-img\"></image>\n        <view class=\"remove-btn\" catchtap=\"removeImage\" data-index=\"{{index}}\">×</view>\n      </view>\n      <view class=\"add-btn\" wx:if=\"{{userImages.length < 9}}\" bindtap=\"chooseImages\">\n        <text class=\"plus-icon\">+</text>\n        <text class=\"add-text\">添加</text>\n      </view>\n    </view>\n    <view wx:if=\"{{userImages.length > 0}}\" class=\"clear-btn-wrap\">\n      <text class=\"clear-all\" catchtap=\"clearImages\">清除全部</text>\n    </view>\n  </view>\n\n  <!-- 场景图片上传 -->\n  <view class=\"section\">\n    <view class=\"section-header\">\n      <text class=\"section-title\">场景图片（可选）</text>\n    </view>\n    <view class=\"scene-section\">\n      <view class=\"scene-box\" wx:if=\"{{!sceneImage}}\" bindtap=\"chooseSceneImage\">\n        <text class=\"scene-placeholder\">+ 添加场景</text>\n      </view>\n      <view class=\"scene-box\" wx:else>\n        <image src=\"{{sceneImage}}\" mode=\"aspectFill\" class=\"scene-img\"></image>\n        <view class=\"remove-btn\" catchtap=\"clearSceneImage\">×</view>\n      </view>\n      <text class=\"scene-hint\">让数字人置身于指定场景中</text>\n    </view>\n  </view>\n\n  <!-- 动作选择（预设） -->\n  <view class=\"section\">\n    <view class=\"section-header\">\n      <text class=\"section-title\">选择动作（预设）</text>\n    </view>\n    <view class=\"action-list\">\n      <view wx:for=\"{{actions}}\" wx:key=\"id\" class=\"action-item {{selectedAction === item.id ? 'active' : ''}}\" style=\"{{selectedAction === item.id ? 'border-color:' + themeColors.primary + ';background:' + themeColors.primary + ';' : ''}}\" bindtap=\"selectAction\" data-action=\"{{item.id}}\">\n        <text class=\"action-icon\">{{item.icon}}</text>\n        <text class=\"action-name {{selectedAction === item.id ? 'active' : ''}}\">{{item.name}}</text>\n      </view>\n    </view>\n  </view>\n\n  <!-- 动作描述 -->\n  <view class=\"section\">\n    <view class=\"section-header\">\n      <text class=\"section-title\">动作描述</text>\n    </view>\n    <view class=\"action-input-wrap\">\n      <textarea class=\"action-input\" placeholder=\"用文字描述动作，如：挥动手臂、点头、走路、转身等\" bindinput=\"onActionInput\" value=\"{{actionPrompt}}\" maxlength=\"200\" auto-height></textarea>\n      <text class=\"char-count\">{{actionPrompt.length}}/200</text>\n    </view>\n  </view>\n\n  <!-- 视频时长选择 -->\n  <view class=\"section\">\n    <view class=\"section-header\">\n      <text class=\"section-title\">视频时长（点击按钮选择）</text>\n    </view>\n    <picker mode=\"selector\" range=\"{{videoDurations}}\" range-key=\"name\" bindchange=\"onDurationChange\" value=\"{{selectedDuration}}\">\n      <view class=\"picker-btn\" style=\"background: {{themeColors.primary}}\">\n        当前时长：{{selectedDuration}}秒\n      </view>\n    </picker>\n  </view>\n\n  <!-- 音频输入 -->\n  <view class=\"section\">\n    <text class=\"section-title\">音频输入</text>\n    <view class=\"audio-controls\">\n      <button class=\"record-btn {{isRecording ? 'recording' : ''}}\" style=\"background: {{isRecording ? '#e74c3c' : themeColors.primary}}\" bindtap=\"toggleRecord\" disabled=\"{{!userImages.length}}\">{{isRecording ? '🔴 录音中...' : '🎤 点击录音'}}</button>\n      <button class=\"upload-btn\" style=\"background: {{themeColors.primary}}\" bindtap=\"chooseAudioFile\" disabled=\"{{!userImages.length}}\">📁 上传录音</button>\n      <view wx:if=\"{{audioFile}}\" class=\"audio-info\">\n        <text>录音已保存</text>\n        <text class=\"clear-audio\" catchtap=\"clearAudio\">清除</text>\n      </view>\n    </view>\n    <view class=\"text-input-section\">\n<input class=\"text-input\" placeholder=\"或输入文字，自动合成语音\" bindinput=\"onInputText\" value=\"{{inputText}}\"/>\n</view>\n</view>\n\n\n<view class=\"generate-section\">\n<button class=\"generate-btn {{isGenerating ? 'disabled' : ''}}\" style=\"background: {{themeColors.primary}}\" bindtap=\"generateVideo\" disabled=\"{{isGenerating || !userImages.length}}\">{{isGenerating ? '生成中...' : '🚀 生成数字人视频'}}</button>\n</view>\n\n\n<view class=\"status-indicator\" wx:if=\"{{isGenerating || statusText}}\">\n<text class=\"status-text\">{{statusText}}</text>\n</view>\n\n\n<view wx:if=\"{{videoUrl}}\" class=\"result-section\">\n<text class=\"section-title\">生成结果</text>\n<view class=\"video-preview\">\n<video src=\"{{videoUrl}}\" class=\"video-player\" controls></video>\n</view>\n<view class=\"result-actions\">\n<button class=\"action-btn primary\" style=\"background: {{themeColors.primary}}\" bindtap=\"saveVideo\">保存到相册</button>\n<button class=\"action-btn secondary\" bindtap=\"previewVideo\">分享</button>\n</view>\n</view>\n</view>\n", "css": "/* pages/digital/digital.wxss */\n.container { min-height: var(--page-height); padding: calc(20 * var(--rpx)); padding-bottom: calc(40 * var(--rpx)); }\n.header { text-align: center; padding: calc(30 * var(--rpx)) 0; border-radius: 0 0 calc(30 * var(--rpx)) calc(30 * var(--rpx)); }\n.title { display: block; font-size: calc(48 * var(--rpx)); font-weight: bold; color: #fff; margin-bottom: calc(10 * var(--rpx)); }\n.subtitle { display: block; font-size: calc(28 * var(--rpx)); color: rgba(255,255,255,0.8); }\n.section { background: rgba(255,255,255,0.9); border-radius: calc(20 * var(--rpx)); padding: calc(30 * var(--rpx)); margin: calc(20 * var(--rpx)); box-shadow: 0 calc(2 * var(--rpx)) calc(10 * var(--rpx)) rgba(0,0,0,0.05); }\n.section-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: calc(20 * var(--rpx)); }\n.section-title { font-size: calc(32 * var(--rpx)); font-weight: bold; color: #333; }\n.section-hint { font-size: calc(24 * var(--rpx)); color: #999; }\n.images-grid { display: flex; flex-wrap: wrap; gap: calc(20 * var(--rpx)); }\n.image-item { position: relative; width: calc(200 * var(--rpx)); height: calc(200 * var(--rpx)); border-radius: calc(16 * var(--rpx)); overflow: hidden; }\n.thumb-img { width: 100%; height: 100%; }\n.remove-btn { position: absolute; top: calc(10 * var(--rpx)); right: calc(10 * var(--rpx)); width: calc(40 * var(--rpx)); height: calc(40 * var(--rpx)); background: rgba(0,0,0,0.6); border-radius: 50%; color: #fff; font-size: calc(28 * var(--rpx)); display: flex; align-items: center; justify-content: center; }\n.add-btn { width: calc(200 * var(--rpx)); height: calc(200 * var(--rpx)); border-radius: calc(16 * var(--rpx)); border: calc(4 * var(--rpx)) dashed #ddd; display: flex; flex-direction: column; align-items: center; justify-content: center; }\n.plus-icon { font-size: calc(60 * var(--rpx)); color: #ccc; }\n.add-text { font-size: calc(24 * var(--rpx)); color: #999; margin-top: calc(10 * var(--rpx)); }\n.clear-btn-wrap { margin-top: calc(20 * var(--rpx)); text-align: center; }\n.clear-all { color: #ff6b6b; font-size: calc(26 * var(--rpx)); }\n.scene-section { display: flex; flex-direction: column; align-items: center; }\n.scene-box { width: calc(300 * var(--rpx)); height: calc(200 * var(--rpx)); border-radius: calc(16 * var(--rpx)); border: calc(4 * var(--rpx)) dashed #ddd; display: flex; align-items: center; justify-content: center; position: relative; overflow: hidden; }\n.scene-placeholder { font-size: calc(32 * var(--rpx)); color: #ccc; }\n.scene-img { width: 100%; height: 100%; }\n.scene-hint { font-size: calc(24 * var(--rpx)); color: #999; margin-top: calc(10 * var(--rpx)); }\n.action-list { display: flex; flex-wrap: wrap; gap: calc(20 * var(--rpx)); }\n.action-item { display: flex; flex-direction: column; align-items: center; padding: calc(20 * var(--rpx)) calc(30 * var(--rpx)); border-radius: calc(16 * var(--rpx)); background: #f5f5f5; min-width: calc(120 * var(--rpx)); border: calc(2 * var(--rpx)) solid transparent; }\n.action-item.active { border-color: inherit; }\n.action-icon { font-size: calc(48 * var(--rpx)); }\n.action-name { font-size: calc(24 * var(--rpx)); color: #666; margin-top: calc(8 * var(--rpx)); }\n.action-name.active { color: #fff; }\n.action-input-wrap { position: relative; }\n.action-input { width: 100%; min-height: calc(120 * var(--rpx)); background: #f5f5f5; border-radius: calc(16 * var(--rpx)); padding: calc(20 * var(--rpx)); font-size: calc(28 * var(--rpx)); box-sizing: border-box; }\n.char-count { position: absolute; bottom: calc(20 * var(--rpx)); right: calc(20 * var(--rpx)); font-size: calc(24 * var(--rpx)); color: #999; }\n.audio-controls { display: flex; align-items: center; gap: calc(20 * var(--rpx)); margin-bottom: calc(20 * var(--rpx)); flex-wrap: wrap; }\n.record-btn, .upload-btn { background: #667eea; color: #fff; border-radius: calc(50 * var(--rpx)); padding: calc(20 * var(--rpx)) calc(30 * var(--rpx)); font-size: calc(26 * var(--rpx)); margin-right: calc(10 * var(--rpx)); }\n.record-btn.recording { background: #e74c3c; animation: pulse 1s infinite; }\n@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.7; } }\n.audio-info { display: flex; align-items: center; gap: calc(10 * var(--rpx)); font-size: calc(24 * var(--rpx)); color: #666; width: 100%; }\n.clear-audio { color: #ff6b6b; padding: calc(10 * var(--rpx)); }\n.text-input { width: 100%; height: calc(80 * var(--rpx)); background: #f5f5f5; border-radius: calc(40 * var(--rpx)); padding: 0 calc(30 * var(--rpx)); font-size: calc(28 * var(--rpx)); box-sizing: border-box; }\n.generate-section { margin: calc(30 * var(--rpx)) calc(20 * var(--rpx)); }\n.generate-btn { width: 100%; height: calc(100 * var(--rpx)); background: linear-gradient(90deg, #667eea, #764ba2); color: #fff; border-radius: calc(50 * var(--rpx)); font-size: calc(36 * var(--rpx)); font-weight: bold; display: flex; align-items: center; justify-content: center; }\n.generate-btn.disabled { background: #ccc; }\n.status-indicator { margin: calc(20 * var(--rpx)); padding: calc(20 * var(--rpx)); background: rgba(255,255,255,0.9); border-radius: calc(16 * var(--rpx)); text-align: center; }\n.status-text { font-size: calc(28 * var(--rpx)); color: #666; }\n.result-section { background: rgba(255,255,255,0.9); border-radius: calc(20 * var(--rpx)); padding: calc(30 * var(--rpx)); margin: calc(20 * var(--rpx)); }\n.video-preview { width: 100%; border-radius: calc(16 * var(--rpx)); overflow: hidden; margin-bottom: calc(20 * var(--rpx)); }\n.video-player { width: 100%; height: calc(400 * var(--rpx)); }\n.result-actions { display: flex; gap: calc(20 * var(--rpx)); }\n.action-btn { flex: 1; height: calc(80 * var(--rpx)); border-radius: calc(40 * var(--rpx)); font-size: calc(28 * var(--rpx)); display: flex; align-items: center; justify-content: center; }\n.action-btn.primary { background: #667eea; color: #fff; }\n.action-btn.secondary { background: #f5f5f5; color: #666; }\n.talking { animation: talk 0.5s ease-in-out infinite; }\n@keyframes talk { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.02); } }\n.smiling { animation: smile 1s ease-in-out infinite; }\n@keyframes smile { 0%, 100% { transform: translateY(0) rotate(0deg); } 50% { transform: translateY(calc(-5 * var(--rpx))) rotate(1deg); } }\n.nodding { animation: nod 0.8s ease-in-out infinite; }\n@keyframes nod { 0%, 100% { transform: translateY(0); } 25% { transform: translateY(calc(-10 * var(--rpx))); } 75% { transform: translateY(calc(10 * var(--rpx))); } }\n.waving { animation: wave 0.6s ease-in-out infinite; transform-origin: bottom center; }\n@keyframes wave { 0%, 100% { transform: rotate(0deg); } 25% { transform: rotate(-5deg); } 75% { transform: rotate(5deg); } }\n.serious { animation: seriousAnim 2s ease-in-out infinite; }\n@keyframes seriousAnim { 0%, 100% { filter: brightness(1); } 50% { filter: brightness(0.95); } }\n.listening { animation: listen 1.5s ease-in-out infinite; }\n@keyframes listen { 0%, 100% { box-shadow: 0 0 calc(20 * var(--rpx)) rgba(102,126,234,0.3); transform: scale(1); } 50% { box-shadow: 0 0 calc(40 * var(--rpx)) rgba(102,126,234,0.6); transform: scale(1.02); } }\n.picker-btn {display: flex;align-items: center;justify-content: center;padding: calc(20 * var(--rpx)) calc(40 * var(--rpx));border-radius: calc(16 * var(--rpx));color: #fff;\nfont-size: calc(28 * var(--rpx));}", "js": "// pages/digital/digital.js\nvar app = getApp();\nPage({\ndata: {\napiBaseUrl: 'http://127.0.0.1:9',\nuserImages: [],\nuploadedImageUrls: [],\nsceneImage: '',\nuploadedSceneUrl: '',\naudioFile: '',\naudioUrl: '',\ninputText: '',\nactionPrompt: '',\nactions: [\n{ id: '自然说话', name: '自然说话', icon: '😊' },\n{ id: '微笑', name: '微笑', icon: '🙂' },\n{ id: '点头', name: '点头', icon: '👍' },\n{ id: '挥手', name: '挥手', icon: '👋' },\n{ id: '严肃', name: '严肃', icon: '😐' }\n],\nselectedAction: '',\nanimationMap: {\n'自然说话': { class: 'talking', label: '💬 说话中' },\n'微笑': { class: 'smiling', label: '😊 微笑' },\n'点头': { class: 'nodding', label: '👍 点头' },\n'挥手': { class: 'waving', label: '👋 挥手' },\n'严肃': { class: 'serious', label: '😐 严肃' }\n},\nisGenerating: false,\ntaskId: '',\nvideoUrl: '',\nstatusText: '请上传数字人照片（最多9张）',\nuserInfo: {},\ncurrentAnimation: '',\nanimationLabel: '',\nthemeColors: {},\nmaxImages: 9,\nvideoDurations: [\n{ id: 5, name: '5秒' },\n{ id: 8, name: '8秒' },\n{ id: 10, name: '10秒' },\n{ id: 15, name: '15秒' }\n],\nselectedDuration: 5\n},\n\nonLoad: function() {\nvar that = this;\nthis.applyTheme();\nwx.getStorage({ key: 'userInfo', success: function(res) { that.setData({ userInfo: res.data || {} }); } });\nwx.getStorage({ key: 'digitalAvatar', success: function(res) { if (res.data) { that.setData({ userImages: [res.data], uploadedImageUrls: [res.data], statusText: '已有形象，请添加更多或描述动作' }); } } });\n},\n\napplyTheme: function() {\nvar theme = wx.getStorageSync('theme') || '默认';\nvar themeColors = app.themeConfig[theme] || app.themeConfig['默认'];\nthis.setData({ themeColors: themeColors });\nwx.setNavigationBarColor({ frontColor: '#ffffff', backgroundColor: themeColors.primary, animation: { duration: 300, timingFunc: 'easeInOut' } });\n},\n\nonShow: function() { this.applyTheme(); },\n\nchooseImages: function() {\nvar that = this;\nvar remaining = this.data.maxImages - this.data.userImages.length;\nif (remaining <= 0) { wx.showToast({ title: '最多上传9张图片', icon: 'none' }); return; }\nwx.chooseMedia({\ncount: remaining,\nmediaType: ['image'],\nsourceType: ['album', 'camera'],\nsuccess: function(res) {\nvar newImages = that.data.userImages.concat(res.tempFiles.map(function(f) { return f.tempFilePath; }));\nif (newImages.length > 9) newImages = newImages.slice(0, 9);\nthat.setData({ userImages: newImages, uploadedImageUrls: [], statusText: '已选择' + newImages.length + '张图片，请描述动作', videoUrl: '' });\n}\n});\n},\n\nclearImages: function() {\nthis.setData({ userImages: [], uploadedImageUrls: [], statusText: '请上传数字人照片（最多9张）', currentAnimation: '', animationLabel: '' });\n},\n\nremoveImage: function(e) {\nvar index = e.currentTarget.dataset.index;\nvar newImages = this.data.userImages.filter(function(_, i) { return i !== index; });\nvar newUrls = this.data.uploadedImageUrls.filter(function(_, i) { return i !== index; });\nthis.setData({ userImages: newImages, uploadedImageUrls: newUrls, statusText: newImages.length > 0 ? '已选择' + newImages.length + '张图片' : '请上传数字人照片（最多9张）' });\n},\n\nchooseSceneImage: function() {\nvar that = this;\nwx.chooseMedia({ count: 1, mediaType: ['image'], sourceType: ['album', 'camera'], success: function(res) { that.setData({ sceneImage: res.tempFiles[0].tempFilePath, uploadedSceneUrl: '', statusText: '场景图片已选择' }); } });\n},\n\nclearSceneImage: function() {\nthis.setData({ sceneImage: '', uploadedSceneUrl: '', statusText: this.data.userImages.length > 0 ? '请描述动作' : '请上传数字人照片' });\n},\n\nonActionInput: function(e) {\nthis.setData({ actionPrompt: e.detail.value, statusText: '动作描述：' + e.detail.value, selectedAction: '' });\n},\n\nselectAction: function(e) {\nvar action = e.currentTarget.dataset.action;\nvar anim = this.data.animationMap[action] || {};\nthis.setData({ selectedAction: action, actionPrompt: action, statusText: '已选择动作：' + action, currentAnimation: anim.class || '', animationLabel: anim.label || '' });\nif (anim.class) { setTimeout(function() { this.setData({ currentAnimation: '', animationLabel: '' }); }.bind(this), 3000); }\n},\n\nonDurationChange: function(e) {\nvar index = e.detail.value;\nvar duration = this.data.videoDurations[index];\nthis.setData({ selectedDuration: duration.id, statusText: '已选择时长：' + duration.name });\n},\n\nstartRecord: function() {\nvar that = this;\nif (this.data.isRecording) return;\nwx.getRecorderManager().start({ format: 'mp3' });\nthis.setData({ isRecording: true, statusText: '录音中...', currentAnimation: 'listening', animationLabel: '👂 倾听中' });\n},\n\nstopRecord: function() {\nvar that = this;\nvar manager = wx.getRecorderManager();\nmanager.onStop(function(res) { that.setData({ audioFile: res.tempFilePath, isRecording: false, statusText: '录音完成，请生成视频', currentAnimation: '', animationLabel: '' }); });\nmanager.stop();\n},\n\ntoggleRecord: function() {\nif (!this.data.userImages.length) { wx.showToast({ title: '请先上传图片', icon: 'none' }); return; }\nif (this.data.isRecording) { this.stopRecord(); } else { this.startRecord(); }\n},\n\nclearAudio: function() { this.setData({ audioFile: '', audioUrl: '', statusText: '请录音或输入文字' }); },\n\nchooseAudioFile: function() {\nvar that = this;\nwx.chooseMedia({ count: 1, mediaType: ['audio'], sourceType: ['album'], success: function(res) {\nvar tempFilePath = res.tempFiles[0].tempFilePath;\nif (tempFilePath && /\\.(mp3|m4a|wav|aac)$/i.test(res.tempFiles[0].name || '')) {\nvar fileSize = res.tempFiles[0].size;\nif (fileSize > 50 * 1024 * 1024) { wx.showToast({ title: '音频文件不能超过50MB', icon: 'none' }); return; }\nthat.setData({ audioFile: tempFilePath, statusText: '音频文件已选择，请生成视频' });\n} else { wx.showToast({ title: '请选择音频文件（mp3/m4a/wav/aac）', icon: 'none' }); }\n}, fail: function() { wx.showToast({ title: '请使用文件管理器选择音频', icon: 'none' }); } });\n},\n\nonInputText: function(e) { this.setData({ inputText: e.detail.value }); },\n\ngenerateVideo: function() {\nvar that = this;\nif (!this.data.userImages.length) { wx.showToast({ title: '请上传数字人图片', icon: 'none' }); return; }\nif (!this.data.audioFile && !this.data.inputText && !this.data.actionPrompt) { wx.showToast({ title: '请填写动作描述或上传音频', icon: 'none' }); return; }\nthat.setData({ isGenerating: true, statusText: '上传图片中...', currentAnimation: 'talking', animationLabel: '💬 上传中' });\nthat.uploadImages(0, []);\n},\n\nuploadImages: function(index, uploadedUrls) {\nvar that = this;\nif (index >= this.data.userImages.length) {\nthis.setData({ uploadedImageUrls: uploadedUrls });\nif (this.data.sceneImage) { that.uploadSceneImage(''); } else { that.processAudio(uploadedUrls, ''); }\nreturn;\n}\nwx.uploadFile({\nurl: that.data.apiBaseUrl + '/api/upload',\nfilePath: that.data.userImages[index],\nname: 'file',\nheader: { 'x-user-openid': wx.getStorageSync('openid') || 'default' },\ntimeout: 600000,\nsuccess: function(res) {\nvar data = JSON.parse(res.data);\nif (data.success) { var imageUrl = data.rawUrl || data.url; uploadedUrls.push(imageUrl); that.uploadImages(index + 1, uploadedUrls); }\nelse { wx.showToast({ title: '图片上传失败', icon: 'none' }); that.setData({ isGenerating: false }); }\n},\nfail: function(err) { wx.showToast({ title: '图片上传超时', icon: 'none' }); that.setData({ isGenerating: false, statusText: '上传超时，请重试' }); }\n});\n},\n\nuploadSceneImage: function(uploadedUrl) {\nvar that = this;\nwx.uploadFile({\nurl: that.data.apiBaseUrl + '/api/upload',\nfilePath: that.data.sceneImage,\nname: 'file',\nheader: { 'x-user-openid': wx.getStorageSync('openid') || 'default' },\ntimeout: 600000,\nsuccess: function(res) {\nvar data = JSON.parse(res.data);\nif (data.success) { var sceneUrl = data.data.rawUrl || data.data.url; that.setData({ uploadedSceneUrl: sceneUrl }); that.processAudio(that.data.uploadedImageUrls, sceneUrl); }\nelse { wx.showToast({ title: '场景图片上传失败', icon: 'none' }); that.setData({ isGenerating: false }); }\n},\nfail: function(err) { wx.showToast({ title: '场景图片上传超时', icon: 'none' }); that.setData({ isGenerating: false }); }\n});\n},\n\nprocessAudio: function(imageUrls, sceneUrl) {\nvar that = this;\nif (this.data.audioFile) {\nthis.setData({ statusText: '上传音频中...' });\nwx.uploadFile({\nurl: that.data.apiBaseUrl + '/api/upload',\nfilePath: that.data.audioFile,\nname: 'file',\nheader: { 'x-user-openid': wx.getStorageSync('openid') || 'default' },\ntimeout: 600000,\nsuccess: function(audioRes) {\nvar audioData = JSON.parse(audioRes.data);\nif (audioData.success) { var audioUrl = audioData.data.rawUrl || audioData.data.url; that.callDigitalHumanAPI(imageUrls, sceneUrl, audioUrl); }\nelse { wx.showToast({ title: '音频上传失败', icon: 'none' }); that.setData({ isGenerating: false }); }\n},\nfail: function() { wx.showToast({ title: '音频上传失败', icon: 'none' }); that.setData({ isGenerating: false }); }\n});\n} else if (this.data.inputText) {\nthis.setData({ statusText: '合成语音中...' });\nwx.request({\nurl: that.data.apiBaseUrl + '/api/voice/tts',\nmethod: 'POST',\nheader: { 'Content-Type': 'application/json' },\ntimeout: 120000,\ndata: { text: that.data.inputText, speakerId: 'S_9IlkOK7X1' },\nsuccess: function(ttsRes) {\nif (ttsRes.data && ttsRes.data.success) { that.callDigitalHumanAPI(imageUrls, sceneUrl, ttsRes.data.audio); }\nelse { wx.showToast({ title: '语音合成失败', icon: 'none' }); that.setData({ isGenerating: false }); }\n},\nfail: function() { wx.showToast({ title: '语音合成失败', icon: 'none' }); that.setData({ isGenerating: false }); }\n});\n} else {\nthat.callDigitalHumanAPI(imageUrls, sceneUrl, '');\n}\n},\n\ncallDigitalHumanAPI: function(imageUrls, sceneUrl, audioUrl) {\nvar that = this;\nthat.setData({ statusText: '提交生成任务...' });\nwx.request({\nurl: that.data.apiBaseUrl + '/api/digital-human/generate',\nmethod: 'POST',\nheader: { 'Content-Type': 'application/json' },\ntimeout: 120000,\ndata: { image_urls: imageUrls, scene_url: sceneUrl || '', action_prompt: that.data.actionPrompt || '', audio_url: audioUrl || '', video_duration: that.data.selectedDuration, output_resolution: 720, pe_fast_mode: true },\nsuccess: function(res) {\nif (res.data && res.data.success) { that.setData({ taskId: res.data.task_id, statusText: '等待生成...' }); that.pollStatus(res.data.task_id, imageUrls[0]); }\nelse { wx.showToast({ title: '提交失败: ' + (res.data && res.data.error), icon: 'none' }); that.setData({ isGenerating: false }); }\n},\nfail: function(err) { wx.showToast({ title: '网络错误', icon: 'none' }); that.setData({ isGenerating: false }); }\n});\n},\n\npollStatus: function(taskId, imageUrl) {\nvar that = this;\nwx.request({\nurl: that.data.apiBaseUrl + '/api/digital-human/status/' + taskId,\ntimeout: 10000,\nsuccess: function(res) {\nif (res.data && res.data.status === 'done') {\nthat.setData({ videoUrl: res.data.video_url, isGenerating: false, statusText: '生成完成！', currentAnimation: '', animationLabel: '' });\nwx.setStorageSync('digitalAvatar', imageUrl);\nwx.showToast({ title: '视频生成完成', icon: 'success' });\n      // 保存到数字人视频历史\n      var digitalHistory = wx.getStorageSync('digitalVideoHistory') || [];\n      digitalHistory.unshift({ id: Date.now(), videoUrl: res.data.video_url, prompt: that.data.actionPrompt || '数字人视频', imageUrls: that.data.uploadedImageUrls, time: new Date().toLocaleString() });\n      if (digitalHistory.length > 20) digitalHistory = digitalHistory.slice(0, 20);\n      wx.setStorageSync('digitalVideoHistory', digitalHistory);\n    } else if (res.data && res.data.status === 'failed') { wx.showToast({ title: '生成失败', icon: 'none' }); that.setData({ isGenerating: false, statusText: '生成失败', currentAnimation: '', animationLabel: '' }); }\n    else { setTimeout(function() { that.pollStatus(taskId, imageUrl); }, 3000); }\n  },\n  fail: function() { setTimeout(function() { that.pollStatus(taskId, imageUrl); }, 3000); }\n});\n},\n\npreviewVideo: function() { if (this.data.videoUrl) { wx.navigateToMiniProgram({ appId: 'wxmp1234567890', path: 'pages/index/index?url=' + encodeURIComponent(this.data.videoUrl), envVersion: 'release' }); } },\n\nsaveVideo: function() {\nvar that = this;\nif (!this.data.videoUrl) return;\nwx.downloadFile({\nurl: that.data.videoUrl,\nsuccess: function(res) { wx.saveVideoToPhotosAlbum({ filePath: res.tempFilePath, success: function() { wx.showToast({ title: '已保存到相册', icon: 'success' }); }, fail: function() { wx.showToast({ title: '保存失败', icon: 'none' }); } }); }\n});\n},\n\ngoToGenerate: function() { wx.navigateTo({ url: '/pages/generate/generate' }); }\n});\n"}, "history": {"markup": "<!-- pages/history/history.wxml -->\n<view class=\"container\" style=\"background: {{themeColors.gradient}}\">\n  <view class=\"history-header\" style=\"background: {{themeColors.header}}\">\n    <text class=\"header-title\">对话历史</text>\n  </view>\n\n  <!-- 顶部tab切换 -->\n  <view class=\"tab-bar\">\n    <view class=\"tab-item {{currentTab === 'chat' ? 'active' : ''}}\" \n          style=\"{{currentTab === 'chat' ? 'color:' + themeColors.primary + ';border-color:' + themeColors.primary : ''}}\"\n          bindtap=\"switchTab\" data-tab=\"chat\">\n      <text>💬 对话</text>\n    </view>\n    <view class=\"tab-item {{currentTab === 'create' ? 'active' : ''}}\" \n          style=\"{{currentTab === 'create' ? 'color:' + themeColors.primary + ';border-color:' + themeColors.primary : ''}}\"\n          bindtap=\"switchTab\" data-tab=\"create\">\n      <text>🎨 AI创作</text>\n    </view>\n    <view class=\"tab-item {{currentTab === 'video' ? 'active' : ''}}\" \n          style=\"{{currentTab === 'video' ? 'color:' + themeColors.primary + ';border-color:' + themeColors.primary : ''}}\"\n          bindtap=\"switchTab\" data-tab=\"video\">\n      <text>🎬 数字人视频</text>\n    </view>\n  </view>\n <!-- 对话历史 -->\n <view wx:if=\"{{currentTab === 'chat'}}\" class=\"tab-content\">\n<view class=\"history-list\">\n<view wx:for=\"{{historyList}}\" wx:key=\"id\" class=\"history-item\">\n<text class=\"history-time\">{{item.time}}</text>\n<text class=\"history-content\">{{item.content}}</text>\n</view>\n</view>\n</view>\n\n\n<view wx:if=\"{{currentTab === 'create'}}\" class=\"tab-content\">\n<view class=\"generate-list\">\n<view wx:for=\"{{generateHistory}}\" wx:key=\"id\" class=\"generate-item\"\nbindtap=\"viewGenerate\" data-item=\"{{item}}\">\n<image wx:if=\"{{item.imageUrl || item.image_url}}\" src=\"{{item.imageUrl || item.image_url}}\" mode=\"aspectFill\" class=\"generate-img\"></image>\n<text class=\"generate-time\">{{item.time || item.created_at}}</text>\n</view>\n</view>\n</view>\n\n\n<view wx:if=\"{{currentTab === 'video'}}\" class=\"tab-content\">\n<view wx:if=\"{{digitalVideoHistory.length === 0}}\" class=\"empty-tip\">\n<text>暂无数字人视频记录</text>\n</view>\n<view class=\"video-list\">\n<view wx:for=\"{{digitalVideoHistory}}\" wx:key=\"id\" class=\"video-item\">\n<video src=\"{{item.videoUrl}}\" class=\"video-thumb\" controls></video>\n<view class=\"video-info\">\n<text class=\"video-prompt\">{{item.prompt}}</text>\n<text class=\"video-time\">{{item.time}}</text>\n</view>\n<view class=\"video-actions\">\n<text class=\"action-btn\" catchtap=\"saveDigitalVideo\" data-url=\"{{item.videoUrl}}\">💾 保存</text>\n</view>\n</view>\n</view>\n</view>\n</view>", "css": "/* pages/history/history.wxss */\n.container {\n  min-height: var(--page-height);\n  background: linear-gradient(180deg, #fff5e6 0%, #ffe4d1 100%);\n  padding: calc(20 * var(--rpx));\n}\n.history-header {\n  text-align: center;\n  padding: calc(20 * var(--rpx));\n}\n.header-title {\n  font-size: calc(36 * var(--rpx));\n  font-weight: bold;\n  color: #8b4513;\n}\n/* Tab切换栏 */\n.tab-bar {\n  display: flex;\n  background: #fff;\n  border-radius: calc(15 * var(--rpx));\n  padding: calc(10 * var(--rpx));\n  margin-bottom: calc(20 * var(--rpx));\n}\n.tab-item {\n  flex: 1;\n  text-align: center;\n  padding: calc(20 * var(--rpx));\n  border-radius: calc(10 * var(--rpx));\n  font-size: calc(28 * var(--rpx));\n  color: #666;\n}\n.tab-item.active {\n  background: linear-gradient(135deg, #ffb347, #ff8c00);\n  color: #fff;\n  font-weight: bold;\n}\n/* 内容区域 */\n.tab-content {\n  background: #fff;\n  border-radius: calc(15 * var(--rpx));\n  padding: calc(20 * var(--rpx));\n  min-height: calc(500 * var(--rpx));\n}\n/* 对话历史 */\n.history-scroll {\n  max-height: calc(600 * var(--rpx));\n}\n.history-item {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: calc(25 * var(--rpx));\n  border-bottom: calc(1 * var(--rpx)) solid #eee;\n}\n.history-item:active {\n  background: rgba(255, 179, 71, 0.1);\n}\n.history-title {\n  font-size: calc(30 * var(--rpx));\n  color: #333;\n}\n.history-time {\n  font-size: calc(24 * var(--rpx));\n  color: #999;\n}\n/* AI创作 */\n.generate-scroll {\n  max-height: calc(600 * var(--rpx));\n}\n.generate-item {\n  margin-bottom: calc(20 * var(--rpx));\n  border-radius: calc(15 * var(--rpx));\n  overflow: hidden;\n  background: #f9f9f9;\n}\n.generate-item image {\n  width: 100%;\n  height: calc(300 * var(--rpx));\n}\n.generate-info {\n  padding: calc(15 * var(--rpx));\n}\n.generate-prompt {\n  font-size: calc(26 * var(--rpx));\n  color: #666;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  display: block;\n}\n/* 空状态提示 */\n.empty-tip {\n  text-align: center;\n  padding: calc(60 * var(--rpx));\n  color: #999;\n  font-size: calc(28 * var(--rpx));\n}\n/* 添加按钮 */\n.add-section {\n  margin-top: calc(30 * var(--rpx));\n  text-align: center;\n}\n.add-btn {\n  width: calc(300 * var(--rpx));\n  height: calc(80 * var(--rpx));\n  background: linear-gradient(135deg, #ffb347, #ff8c00);\n  color: #fff;\n  border-radius: calc(40 * var(--rpx));\n  font-size: calc(30 * var(--rpx));\n  line-height: calc(80 * var(--rpx));\n}\n/* 数字人视频样式 */\n.video-list {\n  padding: calc(20 * var(--rpx));\n}\n.video-item {\n  background: #fff;\n  border-radius: calc(16 * var(--rpx));\n  margin-bottom: calc(20 * var(--rpx));\n  overflow: hidden;\n}\n.video-thumb {\n  width: 100%;\n  height: calc(300 * var(--rpx));\n}\n.video-info {\n  padding: calc(20 * var(--rpx));\n}\n.video-prompt {\n  display: block;\n  font-size: calc(28 * var(--rpx));\n  color: #333;\n  margin-bottom: calc(10 * var(--rpx));\n}\n.video-time {\n  display: block;\n  font-size: calc(24 * var(--rpx));\n  color: #999;\n}\n.video-actions {\n  padding: 0 calc(20 * var(--rpx)) calc(20 * var(--rpx));\n  display: flex;\njustify-content: flex-end;\n}\n\n.action-btn {\npadding: calc(10 * var(--rpx)) calc(30 * var(--rpx));\nbackground: #667eea;\ncolor: #fff;\nborder-radius: calc(30 * var(--rpx));\nfont-size: calc(24 * var(--rpx));\n}", "js": "// pages/history/history.js\nvar app = getApp();\nPage({\ndata: {\napiBaseUrl: 'http://127.0.0.1:9',\ncurrentTab: 'chat',  // chat | create | video\n// 对话历史\nhistoryList: [],\n// AI创作历史\ngenerateHistory: [],\n// 数字人视频历史\ndigitalVideoHistory: [],\n// 主题颜色\nthemeColors: {}\n},\n\nonLoad: function() {\nthis.loadHistory();\nthis.loadGenerateHistory();\nthis.loadDigitalVideoHistory();\nthis.applyTheme();\n},\n\nonShow: function() {\nthis.loadGenerateHistory();\nthis.loadDigitalVideoHistory();\nthis.applyTheme();\n},\n\napplyTheme: function() {\nvar theme = wx.getStorageSync('theme') || '默认';\nvar themeColors = app.themeConfig[theme] || app.themeConfig['默认'];\nthis.setData({ themeColors: themeColors });\nwx.setNavigationBarColor({\nfrontColor: '#ffffff',\nbackgroundColor: themeColors.primary,\nanimation: { duration: 300, timingFunc: 'easeInOut' }\n});\n},\n\nswitchTab: function(e) {\nvar tab = e.currentTarget.dataset.tab;\nthis.setData({ currentTab: tab });\n},\n\nloadHistory: function() {\n  var that = this;\n  // 从本地存储读取对话历史（包含文字和语音）\n  var chatHistory = wx.getStorageSync('chatHistory') || [];\n  // 格式化显示\n  var list = chatHistory.map(function(item) {\n    return { \n      id: item.id, \n      type: item.type || 'text',\n      title: item.title || '新对话', \n      content: item.content,\n      reply: item.reply,\n      time: item.time ? (item.time.substring(0, 10) || '') : ''\n    };\n  });\n  // 按时间倒序排列（最新的在最前）\n  list.reverse();\n  that.setData({ historyList: list });\n  },\n  \n\nloadGenerateHistory: function() {\nvar history = wx.getStorageSync('generateHistory') || [];\nthis.setData({ generateHistory: history });\n},\n\nloadDigitalVideoHistory: function() {\nvar history = wx.getStorageSync('digitalVideoHistory') || [];\nthis.setData({ digitalVideoHistory: history });\n},\n\nnavigateToChat: function(e) {\nvar id = e.currentTarget.dataset.id;\nwx.navigateTo({ url: '/pages/index/index?id=' + id });\n},\n\ngoToVoiceClone: function() { wx.navigateTo({ url: '/pages/voice-clone/voice-clone' }); },\ngoToGenerate: function() { wx.navigateTo({ url: '/pages/generate/generate' }); },\n\npreviewImage: function(e) {\nvar url = e.currentTarget.dataset.url;\nwx.previewImage({ urls: [url] });\n},\n\npreviewDigitalVideo: function(e) {\nvar url = e.currentTarget.dataset.url;\nif (url) {\nwx.navigateToMiniProgram({\nappId: 'wxmp1234567890',\npath: 'pages/index/index?url=' + encodeURIComponent(url),\nenvVersion: 'release'\n});\n}\n},\n\nsaveDigitalVideo: function(e) {\nvar that = this;\nvar url = e.currentTarget.dataset.url;\nif (!url) return;\nwx.downloadFile({\nurl: url,\nsuccess: function(res) {\nwx.saveVideoToPhotosAlbum({\nfilePath: res.tempFilePath,\nsuccess: function() { wx.showToast({ title: '已保存到相册', icon: 'success' }); },\nfail: function() { wx.showToast({ title: '保存失败', icon: 'none' }); }\n});\n}\n});\n}\n});\n"}, "settings": {"markup": "<!-- pages/settings/settings.wxml -->\n<view class=\"container\" style=\"background: {{themeColors.gradient}}\">\n  <!-- 头部 -->\n  <view class=\"settings-header\" >\n    <text class=\"header-title\">设置</text>\n  </view>\n  <!-- 用户信息 -->\n  <view class=\"user-section\">\n    <view class=\"avatar-box\" bindtap=\"changeAvatar\">\n      <image wx:if=\"{{userInfo.avatar}}\" src=\"{{userInfo.avatar}}\" class=\"user-avatar\" mode=\"aspectFill\"></image>\n      <view wx:else class=\"avatar-placeholder\">\n        <text>点击更换</text>\n      </view>\n    </view>\n    <view class=\"user-info-right\">\n      <input \n        class=\"nickname-input\" \n        value=\"{{userInfo.nickname}}\" \n        placeholder=\"设置昵称\"\n        bindconfirm=\"updateNickname\"/>\n      <view wx:if=\"{{userInfo.wechatBadge || userInfo.wechatBound}}\" class=\"wechat-badge\">微信用户</view>\n    </view>\n  </view>\n  <!-- 声音克隆 -->\n  <view class=\"settings-section\">\n    <view class=\"section-title\" style=\"color: {{themeColors.primary}}\">声音克隆</view>\n    \n    <!-- 克隆声音下拉框 -->\n    <view class=\"voice-picker\">\n      <picker mode=\"selector\" range=\"{{clonedVoices}}\" range-key=\"name\" bindchange=\"selectVoice\">\n        <view class=\"picker-display\" style=\"border-color: {{themeColors.primary}}\">\n          <text>{{selectedVoiceName || '选择克隆声音'}}</text>\n          <text class=\"arrow\" style=\"color: {{themeColors.primary}}\">▾</text>\n        </view>\n      </picker>\n      <button class=\"add-voice-btn\" style=\"background: {{themeColors.primary}}\" bindtap=\"goToVoiceClone\">+ 添加</button>\n    </view>\n    \n    <!-- 已选择的声音操作 -->\n    <view wx:if=\"{{selectedVoice}}\" class=\"selected-voice-actions\">\n      <text class=\"play-btn\" style=\"color: {{themeColors.primary}}; border-color: {{themeColors.primary}}\" bindtap=\"playSelectedVoice\">▶ 播放</text>\n      <text class=\"delete-btn\" bindtap=\"deleteSelectedVoice\">🗑 删除</text>\n    </view>\n  </view>\n  <!-- 基本设置 -->\n  <view class=\"settings-section\">\n    <view class=\"section-title\" style=\"color: {{themeColors.primary}}\">基本设置</view>\n    \n    <view class=\"setting-item\">\n      <text class=\"setting-label\">语音识别</text>\n      <switch checked=\"{{voiceEnabled}}\" bindchange=\"toggleVoice\" ></switch>\n    </view>\n    \n    <view class=\"setting-item\">\n      <text class=\"setting-label\">主题颜色</text>\n      <picker mode=\"selector\" range=\"{{themes}}\" bindchange=\"changeTheme\">\n        <view class=\"picker-value\" style=\"color: {{themeColors.primary}}\">{{currentTheme}} ▾</view>\n      </picker>\n    </view>\n    \n    <view class=\"setting-item\">\n      <text class=\"setting-label\">清除历史</text>\n      <button size=\"mini\" style=\"background: {{themeColors.primary}}\" bindtap=\"clearHistory\">清除</button>\n    </view>\n  </view>\n  <!-- 关于 -->\n  <view class=\"settings-section\">\n    <view class=\"section-title\" style=\"color: {{themeColors.primary}}\">关于</view>\n    <view class=\"setting-item\">\n      <text class=\"setting-label\">版本</text>\n      <text class=\"setting-value\">v1.0.0</text>\n    </view>\n  </view>\n  <!-- 退出登录 -->\n  <view class=\"logout-section\">\n    <button class=\"logout-btn\" bindtap=\"logout\">退出登录</button>\n  </view>\n</view>", "css": "/* pages/settings/settings.wxss */\n.container {\n  min-height: var(--page-height);\n  background: linear-gradient(180deg, #fff8f0 0%, #ffe4c9 50%, #ffd4a3 100%);\n  padding-bottom: calc(40 * var(--rpx));\n}\n\n.settings-header {\n  background: linear-gradient(90deg, #ff8c00, #ff6600);\n  padding: calc(40 * var(--rpx));\n  text-align: center;\n}\n\n.header-title {\n  font-size: calc(36 * var(--rpx));\n  font-weight: bold;\n  color: #fff;\n}\n\n/* 用户信息 */\n.user-section {\n  background: rgba(255, 255, 255, 0.9);\n  padding: calc(40 * var(--rpx));\n  display: flex;\n  align-items: flex-start;\n  gap: calc(30 * var(--rpx));\n  margin: calc(30 * var(--rpx));\n  border-radius: calc(20 * var(--rpx));\n  box-shadow: 0 calc(4 * var(--rpx)) calc(20 * var(--rpx)) rgba(255, 140, 0, 0.1);\n}\n\n.avatar-box {\n  width: calc(120 * var(--rpx));\n  height: calc(120 * var(--rpx));\n  border-radius: 50%;\n  overflow: hidden;\n  background: #eee;\n  flex-shrink: 0;\n  border: calc(4 * var(--rpx)) solid #ff8c00;\n}\n\n.user-avatar {\n  width: 100%;\n  height: 100%;\n}\n\n.avatar-placeholder {\n  width: 100%;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: calc(20 * var(--rpx));\n  color: #a0522d;\n  background: rgba(255, 140, 0, 0.1);\n}\n\n.user-info-right {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  gap: calc(12 * var(--rpx));\n}\n\n.nickname-input {\n  font-size: calc(32 * var(--rpx));\n  padding: calc(10 * var(--rpx)) 0;\n  border-bottom: calc(2 * var(--rpx)) solid #ffd4a3;\n  color: #5a3a00;\n}\n\n.wechat-badge {\n  font-size: calc(22 * var(--rpx));\n  color: #07c160;\n  background: rgba(7, 193, 96, 0.1);\n  padding: calc(4 * var(--rpx)) calc(16 * var(--rpx));\n  border-radius: calc(20 * var(--rpx));\n  width: fit-content;\n}\n\n/* 设置区块 */\n.settings-section {\nbackground: rgba(255, 255, 255, 0.9);\nmargin: calc(20 * var(--rpx)) calc(30 * var(--rpx));\nborder-radius: calc(20 * var(--rpx));\npadding: calc(30 * var(--rpx));\nbox-shadow: 0 calc(4 * var(--rpx)) calc(20 * var(--rpx)) rgba(255, 140, 0, 0.1);\n}\n\n.section-title {\nfont-size: calc(28 * var(--rpx));\nfont-weight: bold;\ncolor: #8b4513;\nmargin-bottom: calc(20 * var(--rpx));\npadding-bottom: calc(10 * var(--rpx));\nborder-bottom: calc(2 * var(--rpx)) solid #ffd4a3;\n}\n\n/* 声音克隆 */\n.voice-picker {\ndisplay: flex;\nalign-items: center;\njustify-content: space-between;\nmargin-bottom: calc(20 * var(--rpx));\n}\n\n.picker-display {\nflex: 1;\nheight: calc(70 * var(--rpx));\nbackground: #fff8f0;\nborder: calc(2 * var(--rpx)) solid #ffd4a3;\nborder-radius: calc(35 * var(--rpx));\npadding: 0 calc(30 * var(--rpx));\ndisplay: flex;\nalign-items: center;\njustify-content: space-between;\nfont-size: calc(28 * var(--rpx));\ncolor: #5a3a00;\n}\n\n.add-voice-btn {\nwidth: calc(160 * var(--rpx));\nheight: calc(60 * var(--rpx));\nbackground: linear-gradient(90deg, #ff8c00, #ff6600);\ncolor: #fff;\nborder-radius: calc(30 * var(--rpx));\nfont-size: calc(26 * var(--rpx));\nmargin-left: calc(20 * var(--rpx));\n}\n\n.selected-voice-actions {\ndisplay: flex;\ngap: calc(30 * var(--rpx));\npadding: calc(20 * var(--rpx));\nbackground: #fff8f0;\nborder-radius: calc(16 * var(--rpx));\n}\n\n.selected-voice-actions .play-btn {\ncolor: #ff8c00;\npadding: calc(10 * var(--rpx)) calc(20 * var(--rpx));\nbackground: #fff;\nborder-radius: calc(30 * var(--rpx));\nborder: calc(2 * var(--rpx)) solid #ff8c00;\n}\n\n.selected-voice-actions .delete-btn {\ncolor: #e74c3c;\npadding: calc(10 * var(--rpx)) calc(20 * var(--rpx));\nbackground: #fff;\nborder-radius: calc(30 * var(--rpx));\nborder: calc(2 * var(--rpx)) solid #e74c3c;\n}\n\n/* 设置项 */\n.setting-item {\ndisplay: flex;\njustify-content: space-between;\nalign-items: center;\npadding: calc(25 * var(--rpx)) 0;\nborder-bottom: calc(1 * var(--rpx)) solid #ffd4a3;\n}\n\n.setting-item:last-child {\nborder-bottom: none;\n}\n\n.setting-label {\nfont-size: calc(30 * var(--rpx));\ncolor: #5a3a00;\n}\n\n.setting-value {\nfont-size: calc(28 * var(--rpx));\ncolor: #a0522d;\n}\n\n.picker-value {\nfont-size: calc(28 * var(--rpx));\ncolor: #ff8c00;\n}\n\n/* 退出登录 */\n.logout-section {\nmargin: calc(40 * var(--rpx)) calc(30 * var(--rpx));\n}\n\n.logout-btn {\nwidth: 100%;\nheight: calc(96 * var(--rpx));\nbackground: rgba(255, 255, 255, 0.9);\ncolor: #e74c3c;\nborder: calc(2 * var(--rpx)) solid #e74c3c;\nborder-radius: calc(48 * var(--rpx));\nfont-size: calc(32 * var(--rpx));\n}", "js": "// pages/settings/settings.js\nvar app = getApp();\nPage({\ndata: {\nvoiceEnabled: true,\nthemes: ['默认', '蓝色', '绿色', '紫色'],\ncurrentTheme: '默认',\nuserInfo: {},\nclonedVoices: [],\nselectedVoice: null,\nselectedVoiceName: '',\napiBaseUrl: 'http://127.0.0.1:9',\nthemeColors: {}\n},\n\nonLoad: function() {\nvar that = this;\n// 获取用户信息\nwx.getStorage({\nkey: 'userInfo',\nsuccess: function(res) {\nthat.setData({ userInfo: res.data || {} });\n}\n});\n// 获取已克隆的声音\nthis.loadClonedVoices();\n// 获取当前主题\nvar theme = wx.getStorageSync('theme') || '默认';\nthis.setData({ currentTheme: theme });\nthis.applyTheme(); \n},\n\nonShow: function() {\nvar that = this;\n// 刷新用户信息\nwx.getStorage({\nkey: 'userInfo',\nsuccess: function(res) {\nthat.setData({ userInfo: res.data || {} });\n}\n});\nthis.loadClonedVoices();\n// 刷新当前主题\nvar theme = wx.getStorageSync('theme') || '默认';\nthis.setData({ currentTheme: theme });\nthis.applyTheme(); \n},\n\n// 应用主题颜色\napplyTheme: function() {\n  var theme = wx.getStorageSync('theme') || '默认';\n  var themeColors = app.themeConfig[theme] || app.themeConfig['默认'];\n  this.setData({ themeColors: themeColors });\n  wx.setNavigationBarColor({\n    frontColor: '#ffffff',\n    backgroundColor: themeColors.primary,\n    animation: { duration: 300, timingFunc: 'easeInOut' }\n  });\n},\n\ntoggleVoice: function(e) {\nthis.setData({\nvoiceEnabled: e.detail.value\n});\nwx.setStorageSync('voiceEnabled', e.detail.value);\n},\n\nchangeTheme: function(e) {\n  var that = this;\n  var selectedTheme = this.data.themes[e.detail.value];\n  this.setData({ currentTheme: selectedTheme });\n  wx.setStorageSync('theme', selectedTheme);\n  \n  // 应用主题到全局\n  wx.setStorageSync('themeColors', app.themeConfig[selectedTheme]);\n  \n  wx.showToast({ title: '主题已更换', icon: 'success' });\n  \n  wx.showModal({\n    title: '主题已切换',\n    content: '主题颜色将在下次进入主界面时生效',\n    showCancel: false,\n    confirmText: '知道了'\n  });\n},\n\nclearHistory: function() {\nvar that = this;\nwx.showModal({\ntitle: '确认清除',\ncontent: '确定要清除所有对话历史吗？',\nsuccess: function(res) {\nif (res.confirm) {\nwx.removeStorageSync('chatHistory');\nwx.showToast({\ntitle: '已清除',\nicon: 'success'\n});\n}\n}\n});\n},\n\n// 退出登录\nlogout: function() {\nwx.showModal({\ntitle: '退出登录',\ncontent: '确定要退出登录吗？',\nsuccess: function(res) {\nif (res.confirm) {\nwx.removeStorageSync('userInfo');\nwx.removeStorageSync('openid');\nwx.removeStorageSync('skipWelcome');\nwx.removeStorageSync('selectedVoice');\nwx.reLaunch({ url: '/pages/welcome/welcome' });\n}\n}\n});\n},\n\n// 加载已克隆的声音\nloadClonedVoices: function() {\nvar that = this;\nwx.request({\nurl: that.data.apiBaseUrl + '/api/user/voices',\nsuccess: function(res) {\nif (res.data && res.data.success) {\nthat.setData({ clonedVoices: res.data.voices || [] });\n}\n}\n});\n},\n\n// 跳转到声音克隆页面\ngoToVoiceClone: function() {\nwx.navigateTo({\nurl: '/pages/voice-clone/voice-clone'\n});\n},\n\n// 预览声音\nplayVoice: function(e) {\nvar url = e.currentTarget.dataset.url;\nif (url) {\nwx.downloadFile({\nurl: url,\nsuccess: function(res) {\nwx.playVoice({ filePath: res.tempFilePath });\n}\n});\n}\n},\n\n// 删除声音\ndeleteVoice: function(e) {\nvar that = this;\nvar voiceId = e.currentTarget.dataset.id;\nwx.showModal({\ntitle: '确认删除',\ncontent: '确定要删除这个声音吗？',\nsuccess: function(res) {\nif (res.confirm) {\nwx.showToast({ title: '已删除', icon: 'success' });\nthat.loadClonedVoices();\n}\n}\n});\n},\n\n// 更新用户昵称\nupdateNickname: function(e) {\nvar that = this;\nvar nickname = e.detail.value;\nif (!nickname) return;\nwx.request({\n  url: that.data.apiBaseUrl + '/api/user/nickname',\n  method: 'POST',\n  header: { 'Content-Type': 'application/json' },\n  data: { nickname: nickname },\n  success: function(res) {\n    if (res.data && res.data.success) {\n      that.setData({ userInfo: res.data.user });\n      wx.setStorageSync('userInfo', res.data.user);\n      wx.show\nToast({ title: '昵称已更新', icon: 'success' });\n}\n}\n});\n},\n\n// 选择克隆声音\nselectVoice: function(e) {\nvar index = e.detail.value;\nvar voice = this.data.clonedVoices[index];\nthis.setData({\nselectedVoice: voice,\nselectedVoiceName: voice.name || '克隆声音' + (index + 1)\n});\nwx.setStorageSync('selectedVoice', voice);\n},\n\n// 播放选中的声音\nplaySelectedVoice: function() {\nvar that = this;\nvar voice = this.data.selectedVoice;\nif (!voice || !voice.audio_url) return;\nwx.downloadFile({\n  url: voice.audio_url,\n  success: function(res) {\n    wx.playVoice({ filePath: res.tempFilePath });\n  }\n});\n},\n\n// 删除选中的声音\ndeleteSelectedVoice: function() {\nvar that = this;\nvar voice = this.data.selectedVoice;\nif (!voice) return;\nwx.showModal({\n  title: '确认删除',\n  content: '确定要删除这个声音吗？',\n  success: function(res) {\n    if (res.confirm) {\n      that.setData({ selectedVoice: null, selectedVoiceName: '' });\n      wx.removeStorageSync('selectedVoice');\n      that.loadClonedVoices();\n      wx.showToast({ title: '已删除', icon: 'success' });\n    }\n  }\n});\n},\n\n// 拍照更新头像（修复 rawUrl）\nchangeAvatar: function() {\nvar that = this;\nwx.chooseMedia({\ncount: 1,\nmediaType: ['image'],\nsourceType: ['album', 'camera'],\nsuccess: function(res) {\nwx.uploadFile({\nurl: that.data.apiBaseUrl + '/api/upload',\nfilePath: res.tempFiles[0].tempFilePath,\nname: 'avatar',\nheader: {\n'x-user-openid': wx.getStorageSync('openid') || 'default'\n},\nsuccess: function(uploadRes) {\nvar data = JSON.parse(uploadRes.data);\nvar avatarUrl = data.rawUrl || data.url || (data.data && data.data.rawUrl) || (data.data && data.data.url);\n        if (avatarUrl) {\n          var userInfo = that.data.userInfo;\n          userInfo.avatar = avatarUrl;\n          that.setData({ userInfo: userInfo });\n          wx.setStorageSync('userInfo', userInfo);\n          wx.showToast({ title: '头像已更新', icon: 'success' });\n        } else {\n          wx.showToast({ title: '上传失败', icon: 'none' });\n        }\n      },\n      fail: function() {\n        wx.showToast({ title: '上传失败', icon: 'none' });\n      }\n    });\n  }\n});\n}\n});\n"}, "voice-clone": {"markup": "<!-- pages/voice-clone/voice-clone.wxml -->\n<view class=\"container\">\n  <!-- 头部 -->\n  <view class=\"header\">\n    <text class=\"title\">声音克隆</text>\n    <text class=\"subtitle\">录制或上传音频，克隆你的声音</text>\n  </view>\n\n  <!-- 步骤1: 上传音频 -->\n  <view wx:if=\"{{step === 1}}\" class=\"step-section\">\n    <view class=\"record-section\">\n      <button \n        class=\"record-btn {{isRecording ? 'recording' : ''}}\"\n        bindtap=\"toggleRecord\">\n        {{isRecording ? '🔴 录音中，点击停止' : '🎤 点击录音'}}\n      </button>\n      <view class=\"record-tip\">建议录音30秒以上，效果更好</view>\n    </view>\n\n    <view class=\"divider\">\n      <text>或</text>\n    </view>\n\n    <view class=\"upload-section\">\n      <button class=\"upload-btn\" bindtap=\"chooseAudio\">📁 选择音频文件</button>\n    </view>\n\n    <view wx:if=\"{{audioFile}}\" class=\"audio-preview\">\n      <text class=\"audio-name\">音频已选择</text>\n      <text class=\"clear-btn\" bindtap=\"clearAudio\">清除</text>\n    </view>\n\n    <view class=\"name-section\">\n      <input \n        class=\"name-input\" \n        placeholder=\"输入声音名称，如：我的声音\"\n        bindinput=\"onInputName\"\n        value=\"{{speakerName}}\"/>\n    </view>\n\n    <button \n      class=\"start-btn {{!audioFile || !speakerName ? 'disabled' : ''}}\"\n      bindtap=\"startTrain\"\n      disabled=\"{{!audioFile || !speakerName}}\">\n      开始训练\n    </button>\n  </view>\n\n  <!-- 步骤2: 训练中 -->\n  <view wx:if=\"{{step === 2}}\" class=\"step-section\">\n    <view class=\"training-box\">\n      <view class=\"loading-icon\">⏳</view>\n      <text class=\"training-text\">{{trainingStatus}}</text>\n      <view class=\"progress-bar\">\n        <view class=\"progress-inner\"></view>\n      </view>\n    </view>\n  </view>\n\n  <!-- 步骤3: 完成 -->\n  <view wx:if=\"{{step === 3}}\" class=\"step-section\">\n    <view class=\"success-box\">\n      <view class=\"success-icon\">✅</view>\n      <text class=\"success-text\">声音克隆成功！</text>\n      <text class=\"speaker-id\">Speaker ID: {{speakerId}}</text>\n    </view>\n    <button class=\"back-btn\" bindtap=\"goBack\">完成</button>\n  </view>\n\n  <!-- 状态提示 -->\n  <view wx:if=\"{{trainingStatus}}\" class=\"status-tip\">\n    <text>{{trainingStatus}}</text>\n  </view>\n</view>", "css": "/* pages/voice-clone/voice-clone.wxss */\n.container {\n  min-height: var(--page-height);\n  background: linear-gradient(180deg, #fff5e6 0%, #ffe4d1 100%);\n  padding: calc(20 * var(--rpx));\n  padding-bottom: calc(40 * var(--rpx));\n  min-height: -webkit-fill-available;\n}\n\n.header {\n  text-align: center;\n  padding: calc(30 * var(--rpx)) 0;\n}\n\n.title {\n  display: block;\n  font-size: calc(48 * var(--rpx));\n  font-weight: bold;\n  color: #8b4513;\n  margin-bottom: calc(10 * var(--rpx));\n}\n\n.subtitle {\n  display: block;\n  font-size: calc(28 * var(--rpx));\n  color: #a0522d;\n}\n\n.step-section {\n  background: rgba(255,255,255,0.95);\n  border-radius: calc(20 * var(--rpx));\n  padding: calc(40 * var(--rpx));\n  margin: calc(20 * var(--rpx));\n}\n\n.record-section {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n\n.record-btn {\n  width: calc(300 * var(--rpx));\n  height: calc(300 * var(--rpx));\n  border-radius: 50%;\n  background: linear-gradient(135deg, #ffb347, #ff8c00);\n  color: #fff;\n  font-size: calc(32 * var(--rpx));\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  box-shadow: 0 calc(10 * var(--rpx)) calc(30 * var(--rpx)) rgba(255,179,71,0.4);\n}\n\n.record-btn.recording {\n  background: linear-gradient(135deg, #ff6b6b, #ee5a5a);\n  animation: pulse 1s infinite;\n}\n\n@keyframes pulse {\n  0%, 100% { transform: scale(1); }\n  50% { transform: scale(1.05); }\n}\n\n.record-tip {\n  margin-top: calc(20 * var(--rpx));\n  font-size: calc(24 * var(--rpx));\n  color: #999;\n}\n\n.divider {\n  display: flex;\n  align-items: center;\n  margin: calc(40 * var(--rpx)) 0;\n  color: #999;\n  font-size: calc(28 * var(--rpx));\n}\n\n.divider::before,\n.divider::after {\n  content: '';\n  flex: 1;\n  height: calc(1 * var(--rpx));\n  background: #ddd;\n}\n\n.divider text {\n  padding: 0 calc(20 * var(--rpx));\n}\n\n.upload-section {\n  display: flex;\n  justify-content: center;\n}\n\n.upload-btn {\n  background: #f5f5f5;\n  color: #666;\n  border-radius: calc(50 * var(--rpx));\n  padding: calc(20 * var(--rpx)) calc(60 * var(--rpx));\n  font-size: calc(28 * var(--rpx));\n}\n\n.audio-preview {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin: calc(30 * var(--rpx)) 0;\n  padding: calc(20 * var(--rpx));\n  background: #f9f9f9;\n  border-radius: calc(12 * var(--rpx));\n}\n\n.audio-name {\n  font-size: calc(28 * var(--rpx));\n  color: #333;\n}\n\n.clear-btn {\n  color: #e74c3c;\n  font-size: calc(28 * var(--rpx));\n}\n\n.name-section {\n  margin: calc(30 * var(--rpx)) 0;\n}\n\n.name-input {\n  width: 100%;\n  height: calc(80 * var(--rpx));\n  background: #f5f5f5;\n  border-radius: calc(40 * var(--rpx));\n  padding: 0 calc(30 * var(--rpx));\n  font-size: calc(28 * var(--rpx));\n}\n\n.start-btn {\n  width: 100%;\n  height: calc(88 * var(--rpx));\n  background: linear-gradient(90deg, #ffb347, #ff8c00);\n  color: #fff;\n  border-radius: calc(44 * var(--rpx));\n  font-size: calc(32 * var(--rpx));\n  font-weight: bold;\n}\n\n.start-btn.disabled {\n  background: #ccc;\n}\n\n.training-box {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  padding: calc(60 * var(--rpx)) 0;\n}\n\n.loading-icon {\n  font-size: calc(80 * var(--rpx));\n  margin-bottom: calc(30 * var(--rpx));\n}\n\n.training-text {\n  font-size: calc(32 * var(--rpx));\n  color: #333;\n  margin-bottom: calc(30 * var(--rpx));\n}\n\n.progress-bar {\n  width: 100%;\n  height: calc(10 * var(--rpx));\n  background: #f0f0f0;\n  border-radius: calc(5 * var(--rpx));\n  overflow: hidden;\n}\n\n.progress-inner {\n  width: 60%;\n  height: 100%;\n  background: linear-gradient(90deg, #ffb347, #ff8c00);\n  border-radius: calc(5 * var(--rpx));\n  animation: progress 2s infinite;\n}\n\n@keyframes progress {\n  0% { width: 20%; }\n  100% { width: 80%; }\n}\n\n.success-box {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  padding: calc(60 * var(--rpx)) 0;\n}\n\n.success-icon {\n  font-size: calc(100 * var(--rpx));\n  margin-bottom: calc(30 * var(--rpx));\n}\n\n.success-text {\n  font-size: calc(36 * var(--rpx));\n  font-weight: bold;\n  color: #333;\n  margin-bottom: calc(20 * var(--rpx));\n}\n\n.speaker-id {\n  font-size: calc(24 * var(--rpx));\n  color: #999;\n  word-break: break-all;\n}\n\n.back-btn {\n  width: 100%;\n  height: calc(88 * var(--rpx));\n  background: linear-gradient(90deg, #ffb347, #ff8c00);\n  color: #fff;\n  border-radius: calc(44 * var(--rpx));\n  font-size: calc(32 * var(--rpx));\n  margin-top: calc(40 * var(--rpx));\n}\n\n.status-tip {\n  text-align: center;\n  padding: calc(20 * var(--rpx));\n  font-size: calc(28 * var(--rpx));\n  color: #8b4513;\n}", "js": "// pages/voice-clone/voice-clone.js\nvar app = getApp();\nPage({\ndata: {\napiBaseUrl: 'http://127.0.0.1:9',\naudioFile: '',\nisRecording: false,\nspeakerName: '',\nstep: 1,\ntrainingStatus: '',\nspeakerId: '',\nisTraining: false\n},\n\nstartRecord: function() {\nvar that = this;\nif (this.data.isRecording) return;\nwx.getRecorderManager().start({ format: 'mp3', duration: 60000 });\nthis.setData({ \n  isRecording: true,\n  trainingStatus: '录音中...'\n});\n},\n\nstopRecord: function() {\nvar that = this;\nvar manager = wx.getRecorderManager();\nmanager.onStop(function(res) {\n  that.setData({\n    audioFile: res.tempFilePath,\n    isRecording: false,\n    trainingStatus: '录音完成，请输入名称开始训练'\n  });\n});\nmanager.stop();\n},\n\ntoggleRecord: function() {\nif (this.data.isRecording) {\nthis.stopRecord();\n} else {\nthis.startRecord();\n}\n},\n\nclearAudio: function() {\nthis.setData({\naudioFile: '',\ntrainingStatus: '请录音或上传音频'\n});\n},\n\nchooseAudio: function() {\nvar that = this;\nwx.chooseMedia({\ncount: 1,\nmediaType: ['audio'],\nsourceType: ['album'],\nsuccess: function(res) {\nthat.setData({\naudioFile: res.tempFiles[0].tempFilePath,\ntrainingStatus: '音频已选择，请输入名称开始训练'\n});\n}\n});\n},\n\nonInputName: function(e) {\nthis.setData({ speakerName: e.detail.value });\n},\n\nstartTrain: function() {\nvar that = this;\nif (!this.data.audioFile) {\n  wx.showToast({ title: '请先录音或上传音频', icon: 'none' });\n  return;\n}\nif (!this.data.speakerName) {\n  wx.showToast({ title: '请输入声音名称', icon: 'none' });\n  return;\n}\nthis.setData({ \n  isTraining: true,\n  step: 2,\n  trainingStatus: '上传音频中...'\n});\nvar fs = wx.getFileSystemManager();\nfs.readFile({\n  filePath: that.data.audioFile,\n  encoding: 'base64',\n  success: function(data) {\n    var audioBase64 = data.data;\n    \n    wx.request({\n      url: that.data.apiBaseUrl + '/api/voice/clone',\n      method: 'POST',\n      header: { 'Content-Type': 'application/json' },\n      data: {\n        audio: audioBase64, name: that.data.speakerName,\n        format: 'mp3',\n        language: 0\n      },\n      success: function(res) {\n        if (res.data && res.data.success) {\n          that.setData({\n            speakerId: res.data.speakerId,\n            trainingStatus: '训练中，请稍候...'\n          });\n          that.pollStatus(res.data.speakerId);\n        } else {\n          wx.showToast({ title: res.data.error || '训练失败', icon: 'none' });\n          that.setData({ isTraining: false, step: 1 });\n        }\n      },\n      fail: function() {\n        wx.showToast({ title: '网络错误', icon: 'none' });\n        that.setData({ isTraining: false, step: 1 });\n      }\n    });\n  },\n  fail: function() {\n    wx.showToast({ title: '读取文件失败', icon: 'none' });\n    that.setData({ isTraining: false });\n  }\n});\n},\n\npollStatus: function(speakerId) {\nvar that = this;\nwx.request({\n  url: that.data.apiBaseUrl + '/api/voice/status/' + speakerId,\n  success: function(res) {\n    if (res.data && res.data.success) {\n      var status = res.data.data && res.data.data.status;\n      \n      if (status === 'trained' || status === 'success') {\n        that.setData({\n          step: 3,\n          isTraining: false,\n          trainingStatus: '训练完成！'\n        });\n        wx.showToast({ title: '声音克隆成功', icon: 'success' });\n      } else if (status === 'failed' || status === 'error') {\n        wx.showToast({ title: '训练失败', icon: 'none' });\n        that.setData({ \n          isTraining: false, \n          step: 1,\n          trainingStatus: '训练失败，请重试'\n        });\n      } else {\n        that.setData({ trainingStatus: '训练中...' });\n        setTimeout(function() {\nthat.pollStatus(speakerId);\n}, 3000);\n}\n}\n},\nfail: function() {\nsetTimeout(function() {\nthat.pollStatus(speakerId);\n}, 3000);\n}\n});\n},\n\ngoBack: function() {\nwx.navigateBack();\n}\n});\n"}, "generate": {"markup": "<!--pages/generate/generate.wxml-->\n<view class=\"container\">\n  <!-- 头部 -->\n  <view class=\"header\">\n    <text class=\"title\">AI创作</text>\n    <text class=\"subtitle\">文生图 / 图生图</text>\n  </view>\n  <!-- 模式切换 -->\n  <view class=\"mode-tabs\">\n    <view \n      class=\"tab-item {{mode === 'text2image' ? 'active' : ''}}\"\n      bindtap=\"setMode\"\n      data-mode=\"text2image\">\n      <text>文生图</text>\n    </view>\n    <view \n      class=\"tab-item {{mode === 'image2image' ? 'active' : ''}}\"\n      bindtap=\"setMode\"\n      data-mode=\"image2image\">\n      <text>图生图</text>\n    </view>\n  </view>\n  <!-- 输入区域 -->\n  <view class=\"input-section\">\n    <!-- 文生图：输入描述 -->\n    <view wx:if=\"{{mode === 'text2image'}}\" class=\"prompt-input\">\n      <textarea \n        class=\"prompt-textarea\"\n        placeholder=\"描述你想要生成的图片...&#10;例如：一只可爱的橘猫，萌萌的大眼睛，蓝色背景\"\n        bindinput=\"onInputPrompt\"\n        value=\"{{prompt}}\"\n        maxlength=\"500\"\n        auto-height></textarea>\n    </view>\n    \n    <!-- 图生图：选择图片 -->\n    <view wx:if=\"{{mode === 'image2image'}}\" class=\"image-input\">\n      <!-- 已选择的图片展示 -->\n      <view wx:if=\"{{selectedImages.length > 0}}\" class=\"selected-images-box\">\n        <block wx:for=\"{{selectedImages}}\" wx:key=\"index\">\n          <view class=\"image-item\">\n<image src=\"{{item}}\" mode=\"aspectFill\" class=\"preview-image\"></image>\n<view class=\"delete-btn\" catchtap=\"deleteImage\" data-index=\"{{index}}\">×</view>\n</view>\n</block>\n\n<view wx:if=\"{{selectedImages.length < 9}}\" class=\"add-more-btn\" bindtap=\"chooseImage\">\n<text class=\"plus\">+</text>\n</view>\n</view>\n\n<view wx:else class=\"choose-btn\" bindtap=\"chooseImage\">\n<text class=\"plus\">+</text>\n<text>选择图片（最多9张）</text>\n</view>\n  <!-- 清除按钮 -->\n  <view wx:if=\"{{selectedImages.length > 0}}\" class=\"clear-all-btn\" bindtap=\"clearImage\">\n    <text>清除全部图片</text>\n  </view>\n  \n  <view class=\"prompt-input\">\n    <textarea \n      class=\"prompt-textarea\"\n      placeholder=\"描述你想要的效果...&#10;例如：让这三个人站在沙滩上&#10;，背景是蓝天白云\"\n      bindinput=\"onInputPrompt\"\n      value=\"{{prompt}}\"\n      maxlength=\"500\"\n      auto-height></textarea>\n  </view>\n</view>\n</view>\n\n\n<view class=\"generate-section\">\n<button \nclass=\"generate-btn {{isGenerating ? 'disabled' : ''}}\"\nbindtap=\"generate\"\ndisabled=\"{{isGenerating || !prompt}}\">\n{{isGenerating ? '生成中...' : '🎨 开始生成'}}\n</button>\n</view>\n\n\n<view wx:if=\"{{resultImage}}\" class=\"result-section\">\n<image src=\"{{resultImage}}\" mode=\"widthFix\" class=\"result-image\"></image>\n<view class=\"result-actions\">\n<button class=\"action-btn\" bindtap=\"saveImage\">💾 保存到相册</button>\n<button class=\"action-btn\" bindtap=\"shareImage\">📤 分享</button>\n</view>\n</view>\n\n\n<view wx:if=\"{{history.length > 0}}\" class=\"history-section\">\n<text class=\"section-title\">历史记录</text>\n<scroll-view scroll-x class=\"history-scroll\">\n<view \nwx:for=\"{{history}}\" \nwx:key=\"id\" \nclass=\"history-item\"\nbindtap=\"previewHistory\"\ndata-url=\"{{item.imageUrl}}\">\n<image src=\"{{item.imageUrl}}\" mode=\"aspectFill\"></image>\n</view>\n</scroll-view>\n</view>\n</view>", "css": "/* pages/generate/generate.wxss */\n.container {\n  min-height: var(--page-height);\n  background: linear-gradient(180deg, #fff5e6 0%, #ffe4d1 100%);\n  padding: calc(20 * var(--rpx));\n  padding-bottom: calc(40 * var(--rpx));\n  min-height: -webkit-fill-available;\n}\n.header {\n  text-align: center;\n  padding: calc(30 * var(--rpx)) 0;\n}\n.title {\n  display: block;\n  font-size: calc(48 * var(--rpx));\n  font-weight: bold;\n  color: #8b4513;\n  margin-bottom: calc(10 * var(--rpx));\n}\n.subtitle {\n  display: block;\n  font-size: calc(28 * var(--rpx));\n  color: #a0522d;\n}\n/* 模式切换 */\n.mode-tabs {\n  display: flex;\n  justify-content: center;\n  padding: calc(20 * var(--rpx));\n  background: rgba(255, 255, 255, 0.4);\n  border-radius: calc(20 * var(--rpx));\n  margin: calc(20 * var(--rpx));\n}\n.tab-item {\n  padding: calc(15 * var(--rpx)) calc(60 * var(--rpx));\n  border-radius: calc(30 * var(--rpx));\n  transition: all 0.3s;\n  color: #a0522d;\n}\n.tab-item.active {\n  background: linear-gradient(90deg, #ffb347, #ff8c00);\n  color: #fff;\n}\n/* 输入区域 */\n.input-section {\n  padding: calc(20 * var(--rpx));\n}\n.prompt-input {\n  background: rgba(255, 255, 255, 0.8);\n  border-radius: calc(20 * var(--rpx));\n  padding: calc(20 * var(--rpx));\n  margin-top: calc(20 * var(--rpx));\n}\n.prompt-textarea {\n  width: 100%;\n  min-height: calc(150 * var(--rpx));\n  font-size: calc(28 * var(--rpx));\n  color: #8b4513;\n}\n/* 图片选择 */\n.image-input {\n  padding: calc(20 * var(--rpx));\n}\n/* 多图展示 */\n.selected-images-box {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: flex-start;\n  gap: calc(15 * var(--rpx));\n  margin-bottom: calc(20 * var(--rpx));\n}\n.image-item {\n  position: relative;\n  width: calc(150 * var(--rpx));\n  height: calc(150 * var(--rpx));\n}\n.image-item .preview-image {\n  width: 100%;\n  height: 100%;\n  border-radius: calc(10 * var(--rpx));\n}\n.delete-btn {\n  position: absolute;\n  top: calc(-10 * var(--rpx));\n  right: calc(-10 * var(--rpx));\n  width: calc(40 * var(--rpx));\n  height: calc(40 * var(--rpx));\n  background: rgba(0, 0, 0, 0.6);\n  color: #fff;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: calc(28 * var(--rpx));\n}\n.add-more-btn {\n  width: calc(150 * var(--rpx));\n  height: calc(150 * var(--rpx));\n  display: flex;\n  align-items: center;\n  justify-content: center;\nbackground: rgba(255, 255, 255, 0.5);\nborder: calc(2 * var(--rpx)) dashed #ffb347;\nborder-radius: calc(10 * var(--rpx));\n}\n\n.add-more-btn .plus {\nfont-size: calc(50 * var(--rpx));\ncolor: #ffb347;\n}\n\n.choose-btn {\ndisplay: flex;\nflex-direction: column;\nalign-items: center;\njustify-content: center;\nwidth: calc(300 * var(--rpx));\nheight: calc(300 * var(--rpx));\nmargin: 0 auto;\nbackground: rgba(255, 255, 255, 0.5);\nborder: calc(4 * var(--rpx)) dashed #ffb347;\nborder-radius: calc(20 * var(--rpx));\n}\n\n.choose-btn .plus {\nfont-size: calc(80 * var(--rpx));\ncolor: #ffb347;\n}\n\n.clear-all-btn {\ntext-align: center;\npadding: calc(20 * var(--rpx));\ncolor: #666;\nfont-size: calc(28 * var(--rpx));\nmargin-bottom: calc(20 * var(--rpx));\n}\n\n/* 生成按钮 */\n.generate-section {\npadding: calc(30 * var(--rpx));\n}\n\n.generate-btn {\nwidth: 100%;\nheight: calc(100 * var(--rpx));\nbackground: linear-gradient(90deg, #ffb347, #ff8c00);\ncolor: #fff;\nborder-radius: calc(50 * var(--rpx));\nfont-size: calc(36 * var(--rpx));\ndisplay: flex;\nalign-items: center;\njustify-content: center;\n}\n\n.generate-btn.disabled {\nbackground: #ccc;\n}\n\n/* 结果展示 */\n.result-section {\npadding: calc(20 * var(--rpx));\n}\n\n.result-image {\nwidth: 100%;\nborder-radius: calc(20 * var(--rpx));\n}\n\n.result-actions {\ndisplay: flex;\njustify-content: space-around;\npadding: calc(20 * var(--rpx));\n}\n\n.action-btn {\nflex: 1;\nmargin: 0 calc(10 * var(--rpx));\nheight: calc(80 * var(--rpx));\nbackground: rgba(255, 255, 255, 0.8);\ncolor: #8b4513;\nborder-radius: calc(40 * var(--rpx));\nfont-size: calc(28 * var(--rpx));\ndisplay: flex;\nalign-items: center;\njustify-content: center;\n}\n\n/* 历史记录 */\n.history-section {\npadding: calc(20 * var(--rpx));\n}\n\n.section-title {\nfont-size: calc(30 * var(--rpx));\ncolor: #8b4513;\ndisplay: block;\nmargin-bottom: calc(15 * var(--rpx));\n}\n\n.history-scroll {\nwhite-space: nowrap;\nheight: calc(150 * var(--rpx));\n}\n\n.history-item {\ndisplay: inline-block;\nwidth: calc(120 * var(--rpx));\nheight: calc(120 * var(--rpx));\nmargin-right: calc(15 * var(--rpx));\nborder-radius: calc(15 * var(--rpx));\noverflow: hidden;\n}\n\n.history-item image {\nwidth: 100%;\nheight: 100%;\n}", "js": "// pages/generate/generate.js\nvar app = getApp();\nPage({\ndata: {\napiBaseUrl: 'http://127.0.0.1:9',\n// 生成模式: text2image | image2image\nmode: 'text2image',\n// 输入\nprompt: '',\nselectedImage: '',\nselectedImages: [], // 多图上传支持\n// 状态\nisGenerating: false,\nisUploading: false,\nresultImage: '',\n// 历史记录\nhistory: []\n},\n\nonLoad: function() {\nthis.loadHistory();\n},\n\n// 切换模式\nsetMode: function(e) {\nvar mode = e.currentTarget.dataset.mode;\nthis.setData({\nmode: mode,\nresultImage: '',\nprompt: ''\n});\n},\n\n// 输入提示词\nonInputPrompt: function(e) {\nthis.setData({ prompt: e.detail.value });\n},\n\n// 选择图片（图生图用）- 支持多图\nchooseImage: function() {\nvar that = this;\n// 防止重复上传\nif (this.data.isUploading) {\nwx.showToast({ title: '图片上传中，请稍候', icon: 'none' });\nreturn;\n}\nvar currentCount = that.data.selectedImages ? that.data.selectedImages.length : 0;\nvar maxCount = 9 - currentCount;\nif (maxCount <= 0) {\n  wx.showToast({ title: '最多上传9张图片', icon: 'none' });\n  return;\n}\nwx.chooseMedia({\n  count: maxCount,\n  mediaType: ['image'],\n  sourceType: ['album', 'camera'],\n  success: function(res) {\n    var tempFiles = res.tempFiles;\n    if (!tempFiles || tempFiles.length === 0) return;\n    \n    // 开始上传\n    that.setData({ isUploading: true });\n    wx.showLoading({ title: '图片上传中...' });\n    \n    var uploadedUrls = that.data.selectedImages || [];\n    var totalFiles = tempFiles.length;\n    var completedFiles = 0;\n    \n    // 逐个上传\n    var uploadNext = function(index) {\n      if (index >= totalFiles) {\n        // 全部上传完成\n        that.setData({\n          selectedImages: uploadedUrls,\n          selectedImage: uploadedUrls[0] || '',\n          mode: 'image2image',\n          isUploading: false\n        });\n        wx.hideLoading();\n        wx.showToast({ title: '已上传' + uploadedUrls.length + '张图片', icon: 'success' });\n        return;\n      }\n      \n      var tempPath = tempFiles[index].tempFilePath;\n      \n      wx.uploadFile({\n        url: that.data.apiBaseUrl + '/api/upload',\n        filePath: tempPath,\n        name: 'image',\n        header: {\n          'x-user-openid': wx.getStorageSync('openid') || 'default'\n        },\n        success: function(uploadRes) {\n          var data = JSON.parse(uploadRes.data);\n          if (data.success) {\n            var imageUrl = data.data && data.data.rawUrl || data.data && data.data.url || data.url;\n            uploadedUrls.push(imageUrl);\n          }\n        },\n        fail: function() {\n          wx.showToast({ title: '第' + (index + 1) + '张上传失败', icon: 'none' });\n        },\n        complete: function() {\n          completedFiles++;\n          uploadNext(index + 1);\n        }\n      });\n    };\n    \n    uploadNext(0);\n  }\n});\n},\n\n// 清除图片\nclearImage: function() {\nthis.setData({\nselectedImage: '',\nselectedImages: [],\nmode: 'text2image'\n});\n},\n\n// 删除单张图片\ndeleteImage: function(e) {\nvar index = e.currentTarget.dataset.index;\nvar images = this.data.selectedImages || [];\nimages.splice(index, 1);\nthis.setData({\nselectedImages: images,\nselectedImage: images[0] || ''\n});\n},\n\n// 生成图片\ngenerate: function() {\nvar that = this;\nvar prompt = this.data.prompt.trim();\n// 防止在上传中时生成\nif (this.data.isUploading) {\nwx.showToast({ title: '图片上传中，请稍候', icon: 'none' });\nreturn;\n}\nif (!prompt) {\nwx.showToast({ title: '请输入描述', icon: 'none' });\nreturn;\n}\n// 检查是否有图片（支持多图）\nvar hasImages = this.data.selectedImages && this.data.selectedImages.length > 0;\nif (this.data.mode === 'image2image' && !hasImages) {\n  wx.showToast({ title: '请先选择图片', icon: 'none' });\n  return;\n}\nthis.setData({\nisGenerating: true,\nresultImage: ''\n});\nwx.showLoading({ title: '图片生成中...' });\nvar requestData = {\nprompt: prompt,\nsize: '1024x1024',\nquality: 'standard'\n};\n// 图生图需要传图片URL（支持多图）\nif (this.data.mode === 'image2image' && hasImages) {\n  requestData.image_urls = this.data.selectedImages;\n}\nwx.request({\n  url: that.data.apiBaseUrl + '/api/jimeng/generate',\n  method: 'POST',\n  header: {\n    'content-type': 'application/json'\n  },\n  data: requestData,\n  timeout: 180000,\n  success: function(res) {\n    wx.hideLoading();\n    if (res.data && res.data.success) {\n      var imageUrl = res.data.imageUrl;\n      that.setData({\n        resultImage: imageUrl,\n        isGenerating: false\n      });\n      // 保存到历史记录\n      that.saveToHistory(prompt, imageUrl);\n    } else {\n      wx.showToast({\n        title: res.data && res.data.error || '生成失败',\n        icon: 'none'\n      });\n      that.setData({ isGenerating: false });\n    }\n  },\n  fail: function(err) {\n    wx.hideLoading();\n    wx.showToast({ title: '请求失败', icon: 'none' });\n    that.setData({ isGenerating: false });\n  }\n});\n},\n\n// 保存到历史记录\nsaveToHistory: function(prompt, imageUrl) {\nvar history = this.data.history || [];\nhistory.unshift({\nid: Date.now(),\nprompt: prompt,\nimageUrl: imageUrl,\ntime: new Date().toLocaleString()\n});\n// 只保留最近20条\nif (history.length > 20) {\nhistory = history.slice(0, 20);\n}\nthis.setData({ history: history });\nwx.setStorageSync('generateHistory', history);\n},\n\n// 加载历史记录\nloadHistory: function() {\nvar history = wx.getStorageSync('generateHistory') || [];\nthis.setData({ history: history });\n},\n\n// 保存图片到相册\nsaveImage: function() {\nvar that = this;\nif (!this.data.resultImage) {\nwx.showToast({ title: '没有图片可保存', icon: 'none' });\nreturn;\n}\nwx.downloadFile({\nurl: this.data.resultImage,\nsuccess: function(res) {\nwx.saveImageToPhotosAlbum({\nfilePath: res.tempFilePath,\nsuccess: function() {\nwx.showToast({ title: '已保存到相册', icon: 'success' });\n},\nfail: function(err) {\nconsole.error('保存失败:', err);\nwx.showToast({ title: '保存失败', icon: 'none' });\n}\n});\n},\nfail: function() {\nwx.showToast({ title: '下载失败', icon: 'none' });\n}\n});\n},\n\n// 分享图片\nshareImage: function() {\n// 暂时显示提示\nwx.showToast({ title: '请长按图片分享', icon: 'none' });\n}\n});\n"}}, "tabs": {"color": "#a0522d", "selectedColor": "#ff8c00", "backgroundColor": "#fff8f0", "borderStyle": "black", "list": [{"pagePath": "pages/index/index", "text": "数字人", "iconPath": "assets/tab-home.png", "selectedIconPath": "assets/tab-home-active.png"}, {"pagePath": "pages/digital/digital", "text": "形象", "iconPath": "assets/tab-avatar.png", "selectedIconPath": "assets/tab-avatar-active.png"}, {"pagePath": "pages/history/history", "text": "对话", "iconPath": "assets/tab-chat.png", "selectedIconPath": "assets/tab-chat-active.png"}, {"pagePath": "pages/settings/settings", "text": "我的", "iconPath": "assets/tab-user.png", "selectedIconPath": "assets/tab-user-active.png"}]}, "icons": {"assets/tab-avatar-active.png": "data:image/png;base64,", "assets/tab-user-active.png": "data:image/png;base64,", "assets/tab-chat.png": "data:image/png;base64,", "assets/tab-home-active.png": "data:image/png;base64,", "assets/tab-chat-active.png": "data:image/png;base64,", "assets/tab-avatar.png": "data:image/png;base64,", "assets/tab-user.png": "data:image/png;base64,", "assets/tab-home.png": "data:image/png;base64,"}, "app": "// app.js - 全局配置和API封装\nApp({\n  onLaunch: function () {\n    this.globalData = {\n      apiBaseUrl: 'http://127.0.0.1:9', // 离线体验：禁止请求朋友的服务器\n      currentSessionId: 'web-' + Date.now(),\n      hasLogin: false\n    };\n    \n    // 检查是否设置过主题，没有则默认暖色调\n    if (!wx.getStorageSync('theme')) {\n      wx.setStorageSync('theme', '默认');\n    }\n  },\n\n  // 全局请求封装\n  request: function(options) {\n    const url = options.url.startsWith('http') ? options.url : this.globalData.apiBaseUrl + options.url;\n    return new Promise((resolve, reject) => {\n      wx.request({\n        url: url,\n        method: options.method || 'GET',\n        data: options.data,\n        header: {\n          'Content-Type': options.contentType || 'application/json',\n          ...options.header\n        },\n        success: (res) => {\n          if (res.statusCode === 200) {\n            resolve(res.data);\n          } else {\n            reject(new Error(`HTTP ${res.statusCode}: ${res.data.error || '请求失败'}`));\n          }\n        },\n        fail: (err) => {\n          reject(err);\n        }\n      });\n    });\n  },\n\n  // 获取当前会话ID\n  getCurrentSessionId: function() {\n    return this.globalData.currentSessionId;\n  },\n\n  // ============ 主题配置 ============\n  themeConfig: {\n    '蓝色': {\n      primary: '#4a90e2',\n      secondary: '#5a9fd4',\n      gradient: 'linear-gradient(180deg, #e8f4ff 0%, #cce5ff 50%, #b8d9ff 100%)',\n      header: 'linear-gradient(90deg, #4a90e2, #357abd)',\n      accent: '#4a90e2'\n    },\n    '绿色': {\n      primary: '#52c41a',\n      secondary: '#73d13d',\n      gradient: 'linear-gradient(180deg, #f6ffed 0%, #d9f7be 50%, #b7eb8f 100%)',\n      header: 'linear-gradient(90deg, #52c41a, #389e0d)',\n      accent: '#52c41a'\n    },\n    '紫色': {\n      primary: '#722ed1',\n      secondary: '#9254de',\n      gradient: 'linear-gradient(180deg, #f9f0ff 0%, #efdbff 50%, #d3adf7 100%)',\n      header: 'linear-gradient(90deg, #722ed1, #531dab)',\n      accent: '#722ed1'\n    },\n    '默认': {\n      primary: '#ff8c00',\n      secondary: '#ff6600',\n      gradient: 'linear-gradient(180deg, #fff8f0 0%, #ffe4c9 50%, #ffd4a3 100%)',\n      header: 'linear-gradient(90deg, #ff8c00, #ff6600)',\n      accent: '#ff8c00'\n    }\n  },\n\n  // 获取当前主题\n  getTheme: function() {\n    var theme = wx.getStorageSync('theme');\n    if (!theme) {\n      return this.themeConfig['默认'];\n    }\n    return this.themeConfig[theme] || this.themeConfig['默认'];\n  },\n\n  // 主题列表\n  themeList: ['默认', '蓝色', '绿色', '紫色']\n});\n"};
